def dependency(
    artifact_id,
    family,
    path,
    role,
    comparison_group,
):
    path = Path(path)

    if not path.exists():
        raise FileNotFoundError(path)

    rec = {
        "artifact_id": artifact_id,
        "family": family,
        "role": role,
        "comparison_group": comparison_group,
        "repo_relative_path": relative(path),
        "size_bytes": path.stat().st_size,
        "sha256": sha256_file(path),
    }

    dependency_records.append(rec)
    return rec


