# =============================================================================
# 1. HELPERS
# =============================================================================

def banner(text: str):
    print("\n" + "=" * 104)
    print(text)
    print("=" * 104)


def git(*args):
    p = subprocess.run(
        ["git", *args],
        cwd=REPO_DIR,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(
    path: Path,
    chunk_size: int = 8 * 1024 * 1024,
):
    h = hashlib.sha256()

    with path.open("rb") as f:

        while True:
            chunk = f.read(chunk_size)

            if not chunk:
                break

            h.update(chunk)

    return h.hexdigest()


def sha256_text(text: str):
    return hashlib.sha256(
        text.encode("utf-8")
    ).hexdigest()


def canonical_json_bytes(payload):
    return (
        json.dumps(
            payload,
            indent=2,
            sort_keys=True,
            separators=(",", ": "),
            ensure_ascii=False,
        )
        + "\n"
    ).encode("utf-8")


def write_canonical_json(
    path: Path,
    payload,
):
    raw = canonical_json_bytes(
        payload
    )

    path.write_bytes(raw)

    return hashlib.sha256(
        raw
    ).hexdigest()


def require_file(path: Path):
    if not path.exists():
        raise FileNotFoundError(
            path
        )

    if not path.is_file():
        raise RuntimeError(
            f"Expected regular file: {path}"
        )


def read_int_file(path: Path):
    try:
        return int(
            path.read_text().strip()
        )
    except Exception:
        return None


