# =============================================================================
# HELPERS
# =============================================================================

def banner(text: str):
    print("\n" + "=" * 100)
    print(text)
    print("=" * 100)


def run(
    cmd,
    *,
    cwd=REPO_DIR,
    env=None,
    check=True,
):
    p = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=False,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            "$ " + " ".join(cmd) + "\n\n" + p.stdout
        )

    return p


def git(*args, env=None, check=True):
    return run(
        ["git", *args],
        env=env,
        check=check,
    ).stdout.strip()


def sha256_file(path: Path):
    h = hashlib.sha256()

    with path.open("rb") as f:
        while True:
            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(chunk)

    return h.hexdigest()


def git_blob_bytes(ref: str, path: str):
    """
    Read exact bytes of a file from a git ref without checking it out.
    """
    p = subprocess.run(
        [
            "git",
            "show",
            f"{ref}:{path}",
        ],
        cwd=REPO_DIR,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stderr.decode(
                "utf-8",
                errors="replace",
            )
        )

    return p.stdout


def sha256_bytes(data: bytes):
    return hashlib.sha256(
        data
    ).hexdigest()


