# =============================================================================

banner(
    "STAGE26-0C-GIT :: PUSH"
)


askpass_fd, askpass_path_str = tempfile.mkstemp(
    prefix="stage26_git_askpass_",
    suffix=".sh",
)

os.close(
    askpass_fd
)

askpass_path = Path(
    askpass_path_str
)


askpass_path.write_text(
    """#!/bin/sh
case "$1" in
  *Username*) printf '%s\\n' "x-access-token" ;;
  *Password*) printf '%s\\n' "$GITHUB_TOKEN" ;;
  *)          printf '%s\\n' "" ;;
esac
""",
    encoding="utf-8",
)


askpass_path.chmod(
    stat.S_IRUSR
    |
    stat.S_IWUSR
    |
    stat.S_IXUSR
)


push_env = os.environ.copy()

push_env[
    "GITHUB_TOKEN"
] = github_token

push_env[
    "GIT_ASKPASS"
] = str(
    askpass_path
)

push_env[
    "GIT_TERMINAL_PROMPT"
] = "0"


try:

    push = run(
        [
            "git",
            "push",
            "origin",
            "HEAD:main",
        ],
        env=push_env,
        check=True,
    )

    print(
        push.stdout
    )

finally:

    # Remove credential helper immediately.
    try:
        askpass_path.unlink()
    except FileNotFoundError:
        pass

    push_env.pop(
        "GITHUB_TOKEN",
        None,
    )

    github_token = None


