for target in TARGETS:

    for (
        hardware_mode,
        mode,
    ) in CPU_MODES.items():

        condition_number += 1

        config = {
            "schema":
                "stage26_cpu_preflight_condition_v1",

            "repo":
                str(
                    REPO_DIR
                ),

            "target_id":
                target,

            "hardware_mode":
                hardware_mode,

            "thread_count":
                mode[
                    "threads"
                ],

            "affinity":
                mode[
                    "affinity"
                ],

            "batch_size":
                1,

            "measurement_seed":
                MEASUREMENT_SEED,

            "timing_allowed":
                False,

            "memory_profiling_allowed":
                False,
        }


        config_path = (
            PREFLIGHT_LOCAL_DIR
            / (
                f"preflight_{condition_number:02d}_"
                f"{target}_"
                f"{hardware_mode}.json"
            )
        )


        write_json(
            config_path,
            config,
        )


        env = os.environ.copy()


        thread_count = str(
            mode[
                "threads"
            ]
        )


        # Frozen thread variables passed BEFORE subprocess/framework imports.
        for key in [
            "OMP_NUM_THREADS",
            "MKL_NUM_THREADS",
            "OPENBLAS_NUM_THREADS",
            "NUMEXPR_NUM_THREADS",
            "BLIS_NUM_THREADS",
            "VECLIB_MAXIMUM_THREADS",
        ]:
            env[
                key
            ] = thread_count


        # Prevent accidental GPU path even if environment changes.
        env[
            "CUDA_VISIBLE_DEVICES"
        ] = ""


        p = subprocess.run(
            [
                sys.executable,
                str(
                    WORKER_PATH
                ),
                str(
                    config_path
                ),
            ],
            cwd=REPO_DIR,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False,
        )


        if p.returncode != 0:

            failure = {
                "condition_number":
                    condition_number,

                "target_id":
                    target,

                "hardware_mode":
                    hardware_mode,

                "returncode":
                    p.returncode,

                "stdout":
                    p.stdout[-4000:],

                "stderr":
                    p.stderr[-8000:],
            }

            failures.append(
                failure
            )

            print(
                f"[FAIL] {condition_number:02d}/16 "
                f"{target:43s} "
                f"{hardware_mode}"
            )

            # Fail immediately. Do not continue discovering later
            # compatibility issues after an unresolved preflight failure.
            break


        lines = [
            line.strip()
            for line in p.stdout.splitlines()
            if line.strip()
        ]


        if not lines:
            raise RuntimeError(
                f"No worker JSON returned for {target}"
            )


        try:
            result = json.loads(
                lines[-1]
            )

        except Exception as exc:
            raise RuntimeError(
                "Unable to parse final worker output.\n\n"
                + p.stdout
                + "\n\nSTDERR:\n"
                + p.stderr
            ) from exc


        if result.get(
            "status"
        ) != "PASS":
            raise RuntimeError(
                f"Worker did not return PASS: {result}"
            )


        results.append(
            result
        )


        print(
            f"[PASS] {condition_number:02d}/16 "
            f"{target:43s} "
            f"{hardware_mode:21s} "
            f"output={result['output_sha256'][:16]}..."
        )


    if failures:
        break


