# =============================================================================
# 9. ENVIRONMENT GATE
# =============================================================================

def environment_gate():

    attempts = []

    for attempt in range(
        1,
        ENVIRONMENT_RETRY_COUNT + 1,
    ):

        cpu_percent = float(
            psutil.cpu_percent(
                interval=CPU_UTILIZATION_SAMPLE_SECONDS
            )
        )

        vm = psutil.virtual_memory()

        available_ram_gib = float(
            vm.available
            /
            1024**3
        )

        passed = (
            cpu_percent
            <=
            CPU_UTILIZATION_GATE_PERCENT
            and
            available_ram_gib
            >=
            MIN_AVAILABLE_RAM_GIB
        )

        attempts.append(
            {
                "attempt":
                    attempt,

                "cpu_percent":
                    cpu_percent,

                "available_ram_gib":
                    available_ram_gib,

                "passed":
                    passed,
            }
        )

        if passed:
            return (
                True,
                attempts,
                attempts[-1],
            )

        if attempt < ENVIRONMENT_RETRY_COUNT:

            time.sleep(
                ENVIRONMENT_RETRY_COOLDOWN_SECONDS
            )

    return (
        False,
        attempts,
        attempts[-1],
    )


