def banner(text: str):
    print(
        "\n"
        + "=" * 112
    )

    print(text)

    print(
        "=" * 112
    )


def git(*args):
    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO_DIR,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path: Path):
    h = hashlib.sha256()

    with path.open(
        "rb"
    ) as f:

        while True:

            b = f.read(
                8 * 1024 * 1024
            )

            if not b:
                break

            h.update(b)

    return h.hexdigest()


def sha256_bytes(data: bytes):
    return hashlib.sha256(
        data
    ).hexdigest()


def write_json(
    path: Path,
    obj,
):

    tmp = Path(
        str(path)
        + ".tmp"
    )

    raw = (
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
        )
        + "\n"
    ).encode(
        "utf-8"
    )

    with tmp.open(
        "wb"
    ) as f:

        f.write(raw)

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def stable_seed(text: str):
    digest = hashlib.sha256(
        text.encode(
            "utf-8"
        )
    ).digest()

    return int.from_bytes(
        digest[:8],
        "little",
    ) % (
        2**32
    )


def bootstrap_ci(
    values,
    statistic,
    *,
    seed=BOOTSTRAP_SEED,
    replicates=BOOTSTRAP_REPLICATES,
):

    values = np.asarray(
        values,
        dtype=np.float64,
    )

    if values.size == 0:
        return (
            None,
            None,
        )

    rng = np.random.default_rng(
        int(seed)
    )

    n = int(
        values.size
    )

    estimates = np.empty(
        int(
            replicates
        ),
        dtype=np.float64,
    )

    for i in range(
        int(
            replicates
        )
    ):

        sample = values[
            rng.integers(
                0,
                n,
                size=n,
            )
        ]

        estimates[i] = statistic(
            sample
        )

    return (
        float(
            np.percentile(
                estimates,
                2.5,
            )
        ),
        float(
            np.percentile(
                estimates,
                97.5,
            )
        ),
    )


