def git(*args):
    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(
                chunk
            )

    return h.hexdigest()


def atomic_json(
    path,
    obj,
):
    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def stable_seed(text):
    digest = hashlib.sha256(
        text.encode(
            "utf-8"
        )
    ).digest()

    return int.from_bytes(
        digest[:8],
        "little",
    ) % (
        2**32
    )


def bootstrap_ci(
    values,
    statistic,
    *,
    seed,
    replicates=BOOTSTRAP_REPLICATES,
):
    values = np.asarray(
        values,
        dtype=np.float64,
    )

    if values.size == 0:
        return (
            None,
            None,
        )

    rng = np.random.default_rng(
        int(
            seed
        )
    )

    n = int(
        values.size
    )

    estimates = np.empty(
        replicates,
        dtype=np.float64,
    )

    for i in range(
        replicates
    ):

        sample = values[
            rng.integers(
                0,
                n,
                size=n,
            )
        ]

        estimates[i] = statistic(
            sample
        )

    return (
        float(
            np.percentile(
                estimates,
                2.5,
            )
        ),
        float(
            np.percentile(
                estimates,
                97.5,
            )
        ),
    )


