# 7. ENVIRONMENT GATE
# =============================================================================

def environment_gate():

    attempts = []

    for attempt in range(
        1,
        ENVIRONMENT_RETRY_COUNT + 1,
    ):

        cpu_percent = float(
            psutil.cpu_percent(
                interval=CPU_UTILIZATION_SAMPLE_SECONDS
            )
        )

        available_ram_gib = float(
            psutil.virtual_memory().available
            /
            1024**3
        )

        passed = (
            cpu_percent
            <=
            CPU_UTILIZATION_GATE_PERCENT
            and
            available_ram_gib
            >=
            MIN_AVAILABLE_RAM_GIB
        )

        record = {
            "attempt":
                attempt,

            "cpu_percent":
                cpu_percent,

            "available_ram_gib":
                available_ram_gib,

            "passed":
                passed,
        }

        attempts.append(
            record
        )

        if passed:

            return (
                True,
                attempts,
                record,
            )


        if attempt < ENVIRONMENT_RETRY_COUNT:

            time.sleep(
                ENVIRONMENT_RETRY_COOLDOWN_SECONDS
            )


    return (
        False,
        attempts,
        attempts[-1],
    )


# =============================================================================
# 8. RUN ONE FROZEN CONDITION WITH HEARTBEAT
# =============================================================================

def run_condition(
    condition,
):

    order = int(
        condition[
            "execution_order"
        ]
    )

    target = condition[
        "target_id"
    ]

    mode = condition[
        "hardware_mode"
    ]

    batch_size = int(
        condition[
            "batch_size"
        ]
    )

    threads = int(
        condition[
            "thread_count"
        ]
    )

    affinity = [
        int(x)
        for x in condition[
            "affinity"
        ]
    ]

    warmup_runs = int(
        condition[
            "warmup_runs"
        ]
    )

    timed_runs = int(
        condition[
            "timed_runs"
        ]
    )


    result_path = (
        CONDITION_DIR
        / f"condition_{order:03d}.json"
    )


    if result_path.exists():

        raise RuntimeError(
            f"Condition {order:03d} already has a receipt."
        )


    # Frozen condition cooldown.
    time.sleep(
        CONDITION_COOLDOWN_SECONDS
    )


    env_ok, env_attempts, env_final = (
        environment_gate()
    )


    if not env_ok:

        marker = (
            STEADY
            / "stage26_2_invalid_environment.json"
        )


        atomic_json(
            marker,
            {
                "schema":
                    "stage26_2_invalid_environment_v1",

                "status":
                    "INVALID_ENVIRONMENT",

                "execution_order":
                    order,

                "condition_id":
                    condition[
                        "condition_id"
                    ],

                "target_id":
                    target,

                "hardware_mode":
                    mode,

                "batch_size":
                    batch_size,

                "environment_attempts":
                    env_attempts,

                "completed_condition_orders":
                    sorted(
                        [
                            int(
                                json.loads(
                                    path.read_text(
                                        encoding="utf-8"
                                    )
                                )[
                                    "execution_order"
                                ]
                            )
                            for path in CONDITION_DIR.glob(
                                "condition_*.json"
                            )
                        ]
                    ),
            },
        )


        raise RuntimeError(
            "INVALID_ENVIRONMENT under frozen Stage26 policy."
        )


    config = {
        "schema":
            "stage26_2_worker_config_v1",

        "repo":
            str(
                REPO
            ),

        "result_path":
            str(
                result_path
            ),

        "measurement_seed":
            MEASUREMENT_SEED,

        "condition_id":
            condition[
                "condition_id"
            ],

        "execution_order":
            order,

        "target_id":
            target,

        "target_role":
            condition[
                "target_role"
            ],

        "comparison_group":
            condition[
                "comparison_group"
            ],

        "hardware_mode":
            mode,

        "thread_count":
            threads,

        "affinity":
            affinity,

        "batch_size":
            batch_size,

        "warmup_runs":
            warmup_runs,

        "timed_runs":
            timed_runs,
    }


    config_path = (
        CONFIG_DIR
        / f"condition_{order:03d}.json"
    )


    atomic_json(
        config_path,
        config,
    )


    env = os.environ.copy()

    thread_value = str(
        threads
    )


    for key in [
        "OMP_NUM_THREADS",
        "MKL_NUM_THREADS",
        "OPENBLAS_NUM_THREADS",
        "NUMEXPR_NUM_THREADS",
        "BLIS_NUM_THREADS",
        "VECLIB_MAXIMUM_THREADS",
    ]:

        env[
            key
        ] = thread_value


    env[
        "CUDA_VISIBLE_DEVICES"
    ] = ""


    print(
        f"\n[START] {order:03d}/080 "
        f"{target:43s} "
        f"{mode:21s} "
        f"B={batch_size:5d} "
        f"W={warmup_runs:3d} "
        f"T={timed_runs:3d}",
        flush=True,
    )


    process = subprocess.Popen(
        [
            sys.executable,
            str(
                WORKER
            ),
            str(
                config_path
            ),
        ],
        cwd=REPO,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )


    operational_start = (
        time.monotonic()
    )

    heartbeat_index = 0

    timed_out = False


    while True:

        returncode = (
            process.poll()
        )


        if returncode is not None:
            break


        elapsed_wall = (
            time.monotonic()
            -
            operational_start
        )


        if elapsed_wall >= CONDITION_TIMEOUT_SECONDS:

            timed_out = True

            print(
                f"[TIMEOUT BOUNDARY] {order:03d} "
                f"reached frozen 600-second limit.",
                flush=True,
            )

            process.kill()

            break


        sleep_for = min(
            HEARTBEAT_SECONDS,
            CONDITION_TIMEOUT_SECONDS
            -
            elapsed_wall,
        )


        time.sleep(
            sleep_for
        )


        if process.poll() is None:

            heartbeat_index += 1

            current_wall = int(
                time.monotonic()
                -
                operational_start
            )

            print(
                f"[HEARTBEAT {order:03d}.{heartbeat_index:02d}] "
                f"still running; operational wall ≈ "
                f"{current_wall}s / 600s",
                flush=True,
            )


    stdout, stderr = (
        process.communicate()
    )


    # -------------------------------------------------------------------------
    # Frozen timeout outcome
    # -------------------------------------------------------------------------

    if timed_out:

        atomic_json(
            result_path,
            {
                "schema":
                    "stage26_2_condition_receipt_v1",

                "status":
                    "TIMEOUT_RESOURCE_LIMIT",

                "condition_id":
                    condition[
                        "condition_id"
                    ],

                "execution_order":
                    order,

                "target_id":
                    target,

                "target_role":
                    condition[
                        "target_role"
                    ],

                "comparison_group":
                    condition[
                        "comparison_group"
                    ],

                "hardware_mode":
                    mode,

                "thread_count":
                    threads,

                "affinity_requested":
                    affinity,

                "batch_size":
                    batch_size,

                "warmup_runs":
                    warmup_runs,

                "timed_runs":
                    timed_runs,

                "timeout_seconds":
                    CONDITION_TIMEOUT_SECONDS,

                "environment_attempts":
                    env_attempts,

                "environment_final":
                    env_final,

                "elapsed_ns":
                    [],

                "memory_profiled":
                    False,

                "holdout_accessed":
                    False,

                "gpu_used":
                    False,
            },
        )


    # -------------------------------------------------------------------------
    # No receipt: SIGKILL => frozen resource-limit category
    # -------------------------------------------------------------------------

    elif not result_path.exists():

        if process.returncode in {
            -signal.SIGKILL,
            137,
        }:

            atomic_json(
                result_path,
                {
                    "schema":
                        "stage26_2_condition_receipt_v1",

                    "status":
                        "RESOURCE_LIMIT_OOM",

                    "resource_limit_reason":
                        (
                            "worker terminated by SIGKILL without parent "
                            "timeout; retained as resource-limit/OOM"
                        ),

                    "condition_id":
                        condition[
                            "condition_id"
                        ],

                    "execution_order":
                        order,

                    "target_id":
                        target,

                    "target_role":
                        condition[
                            "target_role"
                        ],

                    "comparison_group":
                        condition[
                            "comparison_group"
                        ],

                    "hardware_mode":
                        mode,

                    "thread_count":
                        threads,

                    "affinity_requested":
                        affinity,

                    "batch_size":
                        batch_size,

                    "warmup_runs":
                        warmup_runs,

                    "timed_runs":
                        timed_runs,

                    "returncode":
                        process.returncode,

                    "environment_attempts":
                        env_attempts,

                    "environment_final":
                        env_final,

                    "elapsed_ns":
                        [],

                    "memory_profiled":
                        False,

                    "holdout_accessed":
                        False,

                    "gpu_used":
                        False,
                },
            )


        else:

            marker = (
                STEADY
                / "stage26_2_worker_failure.json"
            )


            atomic_json(
                marker,
                {
                    "schema":
                        "stage26_2_worker_failure_v1",

                    "status":
                        "WORKER_FAILURE",

                    "execution_order":
                        order,

                    "condition_id":
                        condition[
                            "condition_id"
                        ],

                    "target_id":
                        target,

                    "hardware_mode":
                        mode,

                    "batch_size":
                        batch_size,

                    "returncode":
                        process.returncode,

                    "stdout":
                        stdout[
                            -8000:
                        ],

                    "stderr":
                        stderr[
                            -16000:
                        ],

                    "environment_attempts":
                        env_attempts,
                },
            )


            print(
                "\nSTDOUT:"
            )

            print(
                stdout
            )

            print(
                "\nSTDERR:"
            )

            print(
                stderr
            )


            raise RuntimeError(
                f"Condition {order:03d} failed without durable "
                "resource-limit receipt."
            )


    # -------------------------------------------------------------------------
    # Normalize parent metadata
    # -------------------------------------------------------------------------

    receipt = json.loads(
        result_path.read_text(
            encoding="utf-8"
        )
    )


    receipt[
        "environment_attempts"
    ] = env_attempts

    receipt[
        "environment_final"
    ] = env_final

    receipt[
        "target_role"
    ] = condition[
        "target_role"
    ]

    receipt[
        "comparison_group"
    ] = condition[
        "comparison_group"
    ]


    atomic_json(
        result_path,
        receipt,
    )


    # -------------------------------------------------------------------------
    # Identity / status validation
    # -------------------------------------------------------------------------

    for field in [
        "condition_id",
        "target_id",
        "hardware_mode",
        "thread_count",
        "batch_size",
        "warmup_runs",
        "timed_runs",
    ]:

        if receipt.get(
            field
        ) != condition.get(
            field
        ):

            raise RuntimeError(
                f"Condition {order:03d} receipt differs from frozen "
                f"plan at {field}."
            )


    status = receipt[
        "status"
    ]


    if status == "WORKER_FAILURE":

        marker = (
            STEADY
            / "stage26_2_worker_failure.json"
        )


        atomic_json(
            marker,
            {
                "schema":
                    "stage26_2_worker_failure_v1",

                "status":
                    "WORKER_FAILURE",

                "condition_receipt":
                    receipt,
            },
        )


        raise RuntimeError(
            f"Condition {order:03d} returned WORKER_FAILURE."
        )


    if status not in FINAL_STATUSES:

        raise RuntimeError(
            f"Unexpected condition status: {status}"
        )


    if status == "PASS":

        elapsed = receipt[
            "elapsed_ns"
        ]


        if len(
            elapsed
        ) != timed_runs:

            raise RuntimeError(
                f"Condition {order:03d} timing count mismatch."
            )


        values_ms = (
            np.asarray(
                elapsed,
                dtype=np.float64,
            )
            /
            1_000_000.0
        )


        throughput = (
            float(
                batch_size
            )
            /
            (
                np.asarray(
                    elapsed,
                    dtype=np.float64,
                )
                /
                1e9
            )
        )


        print(
            f"[PASS] {order:03d}/080 "
            f"p50={np.percentile(values_ms,50):10.3f} ms "
            f"p95={np.percentile(values_ms,95):10.3f} ms "
            f"median={np.percentile(throughput,50):12.1f} flow/s",
            flush=True,
        )


    elif status == "RESOURCE_LIMIT_OOM":

        print(
            f"[OOM] {order:03d}/080 "
            f"{target} B={batch_size}",
            flush=True,
        )


    elif status == "TIMEOUT_RESOURCE_LIMIT":

        print(
            f"[TIMEOUT] {order:03d}/080 "
            f"{target} B={batch_size}",
            flush=True,
        )


    return receipt


# =============================================================================
# 9. EXECUTE ONLY 022..080
# =============================================================================

banner(
    "STAGE26-2-RECOVERY-C :: RESUME EXECUTION 022 → 080"
)


for order in range(
    22,
    81,
):

    result_path = (
        CONDITION_DIR
        / f"condition_{order:03d}.json"
    )


    # Safe resume if notebook interrupts again.
    if result_path.exists():

        receipt = json.loads(
            result_path.read_text(
                encoding="utf-8"
            )
        )


        if receipt.get(
            "status"
        ) not in FINAL_STATUSES:

            raise RuntimeError(
                f"Existing condition {order:03d} is not final."
            )


        frozen = condition_by_order[
            order
        ]


        for field in [
            "condition_id",
            "target_id",
            "hardware_mode",
            "thread_count",
            "batch_size",
            "warmup_runs",
            "timed_runs",
        ]:

            if receipt.get(
                field
            ) != frozen.get(
                field
            ):

                raise RuntimeError(
                    f"Existing receipt {order:03d} differs "
                    f"from frozen plan."
                )


        if (
            receipt[
                "status"
            ] == "PASS"
            and
            len(
                receipt.get(
                    "elapsed_ns",
                    [],
                )
            )
            !=
            int(
                frozen[
                    "timed_runs"
                ]
            )
        ):

            raise RuntimeError(
                f"Existing PASS receipt {order:03d} is incomplete."
            )


        print(
            f"[SKIP] {order:03d}/080 already durable "
            f"({receipt['status']})"
        )

        continue


    run_condition(
        condition_by_order[
            order
        ]
    )


# =============================================================================
# 10. ALL-80 COMPLETENESS AUDIT
# =============================================================================

banner(
    "STAGE26-2-RECOVERY-C :: ALL-80 COMPLETENESS AUDIT"
)


all_receipts = []


for order in range(
    1,
    81,
):

    path = (
        CONDITION_DIR
        / f"condition_{order:03d}.json"
    )


    if not path.exists():

        raise RuntimeError(
            f"Missing final condition receipt {order:03d}."
        )


    receipt = json.loads(
        path.read_text(
            encoding="utf-8"
        )
    )


    frozen = condition_by_order[
        order
    ]


    for field in [
        "condition_id",
        "target_id",
        "hardware_mode",
        "thread_count",
        "batch_size",
        "warmup_runs",
        "timed_runs",
    ]:

        if receipt.get(
            field
        ) != frozen.get(
            field
        ):

            raise RuntimeError(
                f"Final condition {order:03d} identity mismatch."
            )


    if receipt[
        "status"
    ] not in FINAL_STATUSES:

        raise RuntimeError(
            f"Condition {order:03d} has invalid final status."
        )


    if receipt[
        "status"
    ] == "PASS":

        if len(
            receipt.get(
                "elapsed_ns",
                [],
            )
        ) != int(
            frozen[
                "timed_runs"
            ]
        ):

            raise RuntimeError(
                f"Condition {order:03d} has incomplete raw timings."
            )


    all_receipts.append(
        receipt
    )


status_counts = {}


for receipt in all_receipts:

    status_counts[
        receipt[
            "status"
        ]
    ] = (
        status_counts.get(
            receipt[
                "status"
            ],
            0,
        )
        +
        1
    )


print(
    "Final condition statuses:"
)


for status, count in sorted(
    status_counts.items()
):

    print(
        f"  {status:30s}: {count}"
    )


print(
    "\n[PASS] 80 / 80 frozen conditions have durable final receipts."
)


# =============================================================================
# 11. BATCH-1 PREDICTION-INTEGRITY GATE
# =============================================================================

banner(
    "STAGE26-2-RECOVERY-C :: BATCH-1 PREDICTION INTEGRITY"
)


preflight = json.loads(
    PREFLIGHT_RECEIPT.read_text(
        encoding="utf-8"
    )
)


expected_b1 = {
    (
        row[
            "target_id"
        ],
        row[
            "hardware_mode"
        ],
    ):
        row[
            "output_sha256"
        ]
    for row in preflight[
        "results"
    ]
}


b1_checked = 0


for receipt in all_receipts:

    if (
        receipt[
            "status"
        ] == "PASS"
        and
        int(
            receipt[
                "batch_size"
            ]
        ) == 1
    ):

        key = (
            receipt[
                "target_id"
            ],
            receipt[
                "hardware_mode"
            ],
        )

        expected_sha = expected_b1[
            key
        ]

        actual_sha = receipt[
            "timed_output_sha256"
        ]


        ok = (
            actual_sha
            ==
            expected_sha
        )


        print(
            f"{receipt['target_id']:43s} "
            f"{receipt['hardware_mode']:21s} "
            f"{'PASS' if ok else 'FAIL'}"
        )


        if not ok:

            raise RuntimeError(
                "Batch-1 prediction fingerprint changed."
            )


        b1_checked += 1


if b1_checked != 16:

    raise RuntimeError(
        f"Expected 16 batch-1 integrity checks; observed {b1_checked}."
    )


