# 10. PUSH IF NEEDED
# =============================================================================

if relationship == "LOCAL_STAGE26_2_AHEAD_BY_ONE":

    banner(
        "STAGE26-2-GIT :: PUSH"
    )


    secret_client = (
        UserSecretsClient()
    )


    aliases = [
        "GITHUB_TOKEN",
        "github_token",
        "GH_TOKEN",
        "gh_token",
        "GITHUB_PAT",
        "github_pat",
        "GH_PAT",
        "gh_pat",
    ]


    token = None

    token_label = None


    for label in aliases:

        try:

            value = (
                secret_client.get_secret(
                    label
                )
            )

        except Exception:

            value = None


        if value:

            token = (
                value.strip()
            )

            token_label = label

            break


    if not token:

        raise RuntimeError(
            "No usable GitHub credential found in Kaggle Secrets."
        )


    print(
        f"[FOUND] {token_label} "
        f"({len(token)} characters)"
    )

    print(
        "Token value will not be printed."
    )


    fd, askpass_name = tempfile.mkstemp(
        prefix="stage26_2_askpass_",
        suffix=".sh",
    )

    os.close(
        fd
    )


    askpass = Path(
        askpass_name
    )


    askpass.write_text(
        """#!/bin/sh
case "$1" in
  *Username*) printf '%s\\n' "x-access-token" ;;
  *Password*) printf '%s\\n' "$GITHUB_TOKEN" ;;
  *)          printf '%s\\n' "" ;;
esac
""",
        encoding="utf-8",
    )


    askpass.chmod(
        stat.S_IRUSR
        |
        stat.S_IWUSR
        |
        stat.S_IXUSR
    )


    push_env = (
        os.environ.copy()
    )


    push_env[
        "GITHUB_TOKEN"
    ] = token

    push_env[
        "GIT_ASKPASS"
    ] = str(
        askpass
    )

    push_env[
        "GIT_TERMINAL_PROMPT"
    ] = "0"


    try:

        result = run(
            [
                "git",
                "push",
                "origin",
                "HEAD:main",
            ],
            env=push_env,
        )


        print(
            result.stdout
        )


    finally:

        try:
            askpass.unlink()

        except FileNotFoundError:
            pass


        token = None


