def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(
                chunk
            )

    return h.hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )


    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )


    os.replace(
        tmp,
        path,
    )


