def banner(text):
    print("\n" + "=" * 112)
    print(text)
    print("=" * 112)


def run(cmd, *, env=None, check=True):

    p = subprocess.run(
        cmd,
        cwd=REPO,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "$ "
            + " ".join(cmd)
            + "\n\n"
            + p.stdout
        )

    return p


def git(*args, env=None, check=True):

    return run(
        [
            "git",
            *args,
        ],
        env=env,
        check=check,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(chunk)

    return h.hexdigest()


def sha256_bytes(data):

    return hashlib.sha256(
        data
    ).hexdigest()


def git_blob_bytes(ref, relpath):

    p = subprocess.run(
        [
            "git",
            "show",
            f"{ref}:{relpath}",
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stderr.decode(
                "utf-8",
                errors="replace",
            )
        )

    return p.stdout


