# =============================================================================
# 3. HELPERS
# =============================================================================

def banner(text):

    print(
        "\n"
        + "=" * 116
    )

    print(text)

    print(
        "=" * 116
    )


def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(
                chunk
            )

    return h.hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def mib(value):

    if value is None:
        return None

    return float(
        value
    ) / 1024**2


def environment_gate():

    attempts = []

    for attempt in range(
        1,
        ENVIRONMENT_RETRY_COUNT + 1,
    ):

        cpu_percent = float(
            psutil.cpu_percent(
                interval=CPU_UTILIZATION_SAMPLE_SECONDS
            )
        )

        available_ram_gib = float(
            psutil.virtual_memory().available
            /
            1024**3
        )

        passed = (
            cpu_percent
            <=
            CPU_UTILIZATION_GATE_PERCENT
            and
            available_ram_gib
            >=
            MIN_AVAILABLE_RAM_GIB
        )

        record = {
            "attempt":
                attempt,

            "cpu_percent":
                cpu_percent,

            "available_ram_gib":
                available_ram_gib,

            "passed":
                passed,
        }

        attempts.append(
            record
        )

        if passed:

            return (
                True,
                attempts,
                record,
            )

        if attempt < ENVIRONMENT_RETRY_COUNT:

            time.sleep(
                ENVIRONMENT_RETRY_COOLDOWN_SECONDS
            )

    return (
        False,
        attempts,
        attempts[
            -1
        ],
    )


# =============================================================================
# 4. PARENT + IMMUTABILITY GATE
# =============================================================================

banner(
    "STAGE26-3B :: PARENT / IMMUTABILITY GATE"
)


head = git(
    "rev-parse",
    "HEAD",
)

remote = git(
    "rev-parse",
    "origin/main",
)

status = git(
    "status",
    "--porcelain",
)


print(
    "Expected HEAD :",
    EXPECTED_HEAD,
)

print(
    "Local HEAD    :",
    head,
)

print(
    "origin/main   :",
    remote,
)

print(
    "Repository clean:",
    status == "",
)


if head != EXPECTED_HEAD:

    raise RuntimeError(
        "Unexpected local HEAD."
    )


if remote != EXPECTED_HEAD:

    raise RuntimeError(
        "origin/main changed after Stage26-3A."
    )


if status:

    raise RuntimeError(
        "Repository must be clean before Stage26-3B:\n"
        +
        status
    )


immutable_checks = [
    (
        "measurement protocol",
        PROTOCOL,
        EXPECTED_PROTOCOL_SHA256,
    ),
    (
        "CPU plan",
        CPU_PLAN,
        EXPECTED_CPU_PLAN_SHA256,
    ),
    (
        "Stage26-2 receipt",
        STAGE26_2_RECEIPT,
        EXPECTED_STAGE26_2_RECEIPT_SHA256,
    ),
    (
        "memory plan",
        MEMORY_PLAN,
        EXPECTED_MEMORY_PLAN_SHA256,
    ),
    (
        "package map",
        PACKAGE_MAP,
        EXPECTED_PACKAGE_MAP_SHA256,
    ),
    (
        "memory worker",
        WORKER,
        EXPECTED_WORKER_SHA256,
    ),
    (
        "memory implementation",
        IMPLEMENTATION,
        EXPECTED_IMPLEMENTATION_SHA256,
    ),
    (
        "freeze receipt",
        FREEZE_RECEIPT,
        EXPECTED_FREEZE_RECEIPT_SHA256,
    ),
    (
        "lock manifest",
        LOCK_MANIFEST,
        EXPECTED_LOCK_MANIFEST_SHA256,
    ),
]


for name, path, expected_sha in immutable_checks:

    actual_sha = sha256_file(
        path
    )

    ok = (
        actual_sha
        ==
        expected_sha
    )

    print(
        f"{name:28s} "
        f"{'PASS' if ok else 'FAIL'} "
        f"{actual_sha}"
    )

    if not ok:

        raise RuntimeError(
            f"Frozen artifact changed: {name}"
        )


# =============================================================================
# 5. LOAD FROZEN 400-REPETITION PLAN
# =============================================================================

banner(
    "STAGE26-3B :: LOAD FROZEN MEMORY PLAN"
)


memory_plan = json.loads(
    MEMORY_PLAN.read_text(
        encoding="utf-8"
    )
)


rows = sorted(
    memory_plan[
        "memory_repetitions"
    ],
    key=lambda row: int(
        row[
            "memory_execution_order"
        ]
    ),
)


if len(
    rows
) != 400:

    raise RuntimeError(
        "Expected exactly 400 frozen memory repetitions."
    )


if [
    int(
        row[
            "memory_execution_order"
        ]
    )
    for row in rows
] != list(
    range(
        1,
        401,
    )
):

    raise RuntimeError(
        "Memory execution order is not exactly 1..400."
    )


print(
    "Frozen memory repetitions:",
    len(
        rows
    ),
)


# =============================================================================
# 6. DOUBLE-RUN / FAILURE-MARKER GATE
# =============================================================================

banner(
    "STAGE26-3B :: RESUME / DOUBLE-RUN GATE"
)


if RESULT_PACKAGE_DIR.exists():

    raise RuntimeError(
        "Stage26-3B repository result package already exists. "
        "Do not remeasure."
    )


for marker in [
    FAILURE_MARKER,
    ENV_FAILURE_MARKER,
]:

    if marker.exists():

        print(
            "Existing non-resource failure marker:"
        )

        print(
            " ",
            marker
        )

        raise RuntimeError(
            "Stage26-3B previously stopped at a methodological/"
            "implementation/environment failure. "
            "Do not silently resume."
        )


existing_paths = sorted(
    OBS_DIR.glob(
        "memory_*.json"
    )
)


print(
    "Existing durable memory observations:",
    len(
        existing_paths
    ),
)


# =============================================================================
# 7. VALIDATE ANY EXISTING RECEIPTS
# =============================================================================

row_by_order = {
    int(
        row[
            "memory_execution_order"
        ]
    ):
        row
    for row in rows
}


completed_orders = set()


for path in existing_paths:

    receipt = json.loads(
        path.read_text(
            encoding="utf-8"
        )
    )

    order = int(
        receipt[
            "memory_execution_order"
        ]
    )


    if order not in row_by_order:

        raise RuntimeError(
            f"Unknown memory execution order {order}."
        )


    frozen = row_by_order[
        order
    ]


    for field in [
        "source_cpu_execution_order",
        "condition_id",
        "target_id",
        "hardware_mode",
        "thread_count",
        "batch_size",
        "memory_repetition",
    ]:

        if receipt.get(
            field
        ) != frozen.get(
            field
        ):

            raise RuntimeError(
                f"Existing memory receipt {order:03d} "
                f"mismatch at {field}."
            )


    if receipt[
        "status"
    ] not in FINAL_STATUSES:

        raise RuntimeError(
            f"Existing memory receipt {order:03d} "
            f"has invalid status {receipt['status']}."
        )


    if receipt[
        "status"
    ] == "PASS":

        required_metrics = [
            "baseline_rss_bytes",
            "loaded_rss_bytes",
            "peak_rss_bytes",
            "delta_model_rss_bytes",
            "delta_peak_rss_bytes",
            "ru_maxrss_bytes_descriptive",
        ]


        for metric in required_metrics:

            if metric not in receipt:

                raise RuntimeError(
                    f"Existing PASS receipt {order:03d} "
                    f"missing {metric}."
                )


    completed_orders.add(
        order
    )


print(
    "Validated durable observations:",
    len(
        completed_orders
    ),
)


# =============================================================================
# 8. SYSTEM RAM CEILING
# =============================================================================

physical_ram_bytes = int(
    psutil.virtual_memory().total
)

worker_ram_limit_bytes = int(
    physical_ram_bytes
    *
    MAX_WORKER_RAM_FRACTION
)


banner(
    "STAGE26-3B :: RESOURCE ENVELOPE"
)


print(
    "Physical RAM:",
    f"{physical_ram_bytes / 1024**3:.3f} GiB",
)

print(
    "85% worker ceiling:",
    f"{worker_ram_limit_bytes / 1024**3:.3f} GiB",
)

print(
    "Parent RSS sampling:",
    "5 ms",
)

print(
    "Resource timeout:",
    "600 s",
)

print(
    "GPU:",
    "OFF",
)


# =============================================================================
# 9. EXECUTE 400 FROZEN MEMORY REPETITIONS
# =============================================================================

banner(
    "STAGE26-3B :: EXECUTE FROZEN MEMORY PLAN"
)


for frozen in rows:

    order = int(
        frozen[
            "memory_execution_order"
        ]
    )


    if order in completed_orders:

        print(
            f"[SKIP] {order:03d}/400 already durable"
        )

        continue


    target = frozen[
        "target_id"
    ]

    mode = frozen[
        "hardware_mode"
    ]

    batch_size = int(
        frozen[
            "batch_size"
        ]
    )

    threads = int(
        frozen[
            "thread_count"
        ]
    )

    affinity = [
        int(x)
        for x in frozen[
            "affinity"
        ]
    ]

    repetition = int(
        frozen[
            "memory_repetition"
        ]
    )


    # -------------------------------------------------------------------------
    # Frozen environment precondition gate.
    # -------------------------------------------------------------------------

    env_ok, env_attempts, env_final = (
        environment_gate()
    )


    if not env_ok:

        atomic_json(
            ENV_FAILURE_MARKER,
            {
                "schema":
                    "stage26_3b_invalid_environment_v1",

                "status":
                    "INVALID_ENVIRONMENT",

                "memory_execution_order":
                    order,

                "target_id":
                    target,

                "hardware_mode":
                    mode,

                "batch_size":
                    batch_size,

                "environment_attempts":
                    env_attempts,

                "completed_memory_orders":
                    sorted(
                        completed_orders
                    ),
            },
        )


        raise RuntimeError(
            "INVALID_ENVIRONMENT under frozen Stage26 rules."
        )


    result_path = (
        OBS_DIR
        / f"memory_{order:03d}.json"
    )

    config_path = (
        CONFIG_DIR
        / f"memory_{order:03d}.json"
    )


    config = {
        "schema":
            "stage26_3_memory_worker_config_v1",

        "repo":
            str(
                REPO
            ),

        "result_path":
            str(
                result_path
            ),

        "measurement_seed":
            MEASUREMENT_SEED,

        "memory_execution_order":
            order,

        "source_cpu_execution_order":
            int(
                frozen[
                    "source_cpu_execution_order"
                ]
            ),

        "condition_id":
            frozen[
                "condition_id"
            ],

        "target_id":
            target,

        "target_role":
            frozen[
                "target_role"
            ],

        "comparison_group":
            frozen[
                "comparison_group"
            ],

        "hardware_mode":
            mode,

        "thread_count":
            threads,

        "affinity":
            affinity,

        "batch_size":
            batch_size,

        "memory_repetition":
            repetition,
    }


    atomic_json(
        config_path,
        config,
    )


    env = os.environ.copy()

    thread_value = str(
        threads
    )


    for key in [
        "OMP_NUM_THREADS",
        "MKL_NUM_THREADS",
        "OPENBLAS_NUM_THREADS",
        "NUMEXPR_NUM_THREADS",
        "BLIS_NUM_THREADS",
        "VECLIB_MAXIMUM_THREADS",
    ]:

        env[
            key
        ] = thread_value


    env[
        "CUDA_VISIBLE_DEVICES"
    ] = ""


    print(
        f"\n[START] {order:03d}/400 "
        f"{target:43s} "
        f"{mode:21s} "
        f"B={batch_size:5d} "
        f"rep={repetition}",
        flush=True,
    )


    process = subprocess.Popen(
        [
            sys.executable,
            str(
                WORKER
            ),
            str(
                config_path
            ),
        ],
        cwd=REPO,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )


    child = psutil.Process(
        process.pid
    )

    operational_start = (
        time.monotonic()
    )

    last_heartbeat = (
        operational_start
    )

    parent_observed_peak_rss = 0

    ram_limit_triggered = False

    timed_out = False


    while True:

        returncode = process.poll()


        if returncode is not None:

            break


        # -------------------------------------------------------------
        # Parent-side worker RSS guard.
        # This is resource protection only, not the reported peak metric.
        # -------------------------------------------------------------

        try:

            current_rss = int(
                child.memory_info().rss
            )

            parent_observed_peak_rss = max(
                parent_observed_peak_rss,
                current_rss,
            )


            if current_rss > worker_ram_limit_bytes:

                ram_limit_triggered = True

                print(
                    f"[RAM LIMIT] {order:03d} "
                    f"worker RSS={current_rss / 1024**3:.3f} GiB "
                    f"> frozen 85% ceiling",
                    flush=True,
                )

                process.kill()

                break


        except psutil.NoSuchProcess:

            pass


        now = time.monotonic()

        operational_elapsed = (
            now
            -
            operational_start
        )


        # Global frozen resource timeout.
        if operational_elapsed >= CONDITION_TIMEOUT_SECONDS:

            timed_out = True

            print(
                f"[TIMEOUT] {order:03d} reached "
                f"frozen 600-second resource limit",
                flush=True,
            )

            process.kill()

            break


        if (
            now
            -
            last_heartbeat
        ) >= HEARTBEAT_SECONDS:

            last_heartbeat = now

            print(
                f"[HEARTBEAT {order:03d}] "
                f"still running; "
                f"worker_peak_seen="
                f"{parent_observed_peak_rss / 1024**3:.3f} GiB",
                flush=True,
            )


        time.sleep(
            RSS_PARENT_SAMPLE_SECONDS
        )


    stdout, stderr = (
        process.communicate()
    )


    # -------------------------------------------------------------------------
    # Parent-forced frozen resource outcomes.
    # -------------------------------------------------------------------------

    if ram_limit_triggered:

        atomic_json(
            result_path,
            {
                "schema":
                    "stage26_3_memory_observation_v1",

                "status":
                    "RESOURCE_LIMIT_OOM",

                "resource_limit_reason":
                    "PARENT_85_PERCENT_PHYSICAL_RAM_CEILING",

                "memory_execution_order":
                    order,

                "source_cpu_execution_order":
                    int(
                        frozen[
                            "source_cpu_execution_order"
                        ]
                    ),

                "condition_id":
                    frozen[
                        "condition_id"
                    ],

                "target_id":
                    target,

                "target_role":
                    frozen[
                        "target_role"
                    ],

                "comparison_group":
                    frozen[
                        "comparison_group"
                    ],

                "hardware_mode":
                    mode,

                "thread_count":
                    threads,

                "affinity_requested":
                    affinity,

                "batch_size":
                    batch_size,

                "memory_repetition":
                    repetition,

                "worker_ram_limit_bytes":
                    worker_ram_limit_bytes,

                "parent_observed_peak_rss_bytes":
                    parent_observed_peak_rss,

                "environment_attempts":
                    env_attempts,

                "environment_final":
                    env_final,

                "timing_performed":
                    False,

                "holdout_accessed":
                    False,

                "gpu_used":
                    False,
            },
        )


    elif timed_out:

        atomic_json(
            result_path,
            {
                "schema":
                    "stage26_3_memory_observation_v1",

                "status":
                    "TIMEOUT_RESOURCE_LIMIT",

                "resource_limit_reason":
                    "FROZEN_600_SECOND_TIMEOUT",

                "memory_execution_order":
                    order,

                "source_cpu_execution_order":
                    int(
                        frozen[
                            "source_cpu_execution_order"
                        ]
                    ),

                "condition_id":
                    frozen[
                        "condition_id"
                    ],

                "target_id":
                    target,

                "target_role":
                    frozen[
                        "target_role"
                    ],

                "comparison_group":
                    frozen[
                        "comparison_group"
                    ],

                "hardware_mode":
                    mode,

                "thread_count":
                    threads,

                "affinity_requested":
                    affinity,

                "batch_size":
                    batch_size,

                "memory_repetition":
                    repetition,

                "timeout_seconds":
                    CONDITION_TIMEOUT_SECONDS,

                "parent_observed_peak_rss_bytes":
                    parent_observed_peak_rss,

                "environment_attempts":
                    env_attempts,

                "environment_final":
                    env_final,

                "timing_performed":
                    False,

                "holdout_accessed":
                    False,

                "gpu_used":
                    False,
            },
        )


    # -------------------------------------------------------------------------
    # Worker ended without its own receipt.
    # -------------------------------------------------------------------------

    elif not result_path.exists():

        stderr_lower = (
            stderr
            or
            ""
        ).lower()


        oom_like = (
            process.returncode
            in {
                -signal.SIGKILL,
                137,
            }
            or
            "out of memory"
            in stderr_lower
            or
            "cannot allocate memory"
            in stderr_lower
            or
            "memoryerror"
            in stderr_lower
            or
            "bad alloc"
            in stderr_lower
        )


        if oom_like:

            atomic_json(
                result_path,
                {
                    "schema":
                        "stage26_3_memory_observation_v1",

                    "status":
                        "RESOURCE_LIMIT_OOM",

                    "resource_limit_reason":
                        "WORKER_OOM_OR_SIGKILL",

                    "memory_execution_order":
                        order,

                    "source_cpu_execution_order":
                        int(
                            frozen[
                                "source_cpu_execution_order"
                            ]
                        ),

                    "condition_id":
                        frozen[
                            "condition_id"
                        ],

                    "target_id":
                        target,

                    "target_role":
                        frozen[
                            "target_role"
                        ],

                    "comparison_group":
                        frozen[
                            "comparison_group"
                        ],

                    "hardware_mode":
                        mode,

                    "thread_count":
                        threads,

                    "affinity_requested":
                        affinity,

                    "batch_size":
                        batch_size,

                    "memory_repetition":
                        repetition,

                    "returncode":
                        process.returncode,

                    "parent_observed_peak_rss_bytes":
                        parent_observed_peak_rss,

                    "environment_attempts":
                        env_attempts,

                    "environment_final":
                        env_final,

                    "timing_performed":
                        False,

                    "holdout_accessed":
                        False,

                    "gpu_used":
                        False,
                },
            )


        else:

            atomic_json(
                FAILURE_MARKER,
                {
                    "schema":
                        "stage26_3b_worker_failure_v1",

                    "status":
                        "WORKER_FAILURE",

                    "memory_execution_order":
                        order,

                    "target_id":
                        target,

                    "hardware_mode":
                        mode,

                    "batch_size":
                        batch_size,

                    "returncode":
                        process.returncode,

                    "stdout":
                        stdout[
                            -8000:
                        ],

                    "stderr":
                        stderr[
                            -16000:
                        ],

                    "parent_observed_peak_rss_bytes":
                        parent_observed_peak_rss,

                    "environment_attempts":
                        env_attempts,
                },
            )


            print(
                "\nWorker stdout:"
            )

            print(
                stdout
            )

            print(
                "\nWorker stderr:"
            )

            print(
                stderr
            )


            raise RuntimeError(
                f"Stage26-3B worker failure at memory order {order:03d}."
            )


    # -------------------------------------------------------------------------
    # Normalize receipt with parent-side metadata.
    # -------------------------------------------------------------------------

    receipt = json.loads(
        result_path.read_text(
            encoding="utf-8"
        )
    )


    receipt[
        "target_role"
    ] = frozen[
        "target_role"
    ]

    receipt[
        "comparison_group"
    ] = frozen[
        "comparison_group"
    ]

    receipt[
        "environment_attempts"
    ] = env_attempts

    receipt[
        "environment_final"
    ] = env_final

    receipt[
        "parent_observed_peak_rss_bytes"
    ] = parent_observed_peak_rss

    receipt[
        "worker_ram_limit_bytes"
    ] = worker_ram_limit_bytes


    atomic_json(
        result_path,
        receipt,
    )


    # -------------------------------------------------------------------------
    # Scientific identity gate.
    # -------------------------------------------------------------------------

    for field in [
        "source_cpu_execution_order",
        "condition_id",
        "target_id",
        "hardware_mode",
        "thread_count",
        "batch_size",
        "memory_repetition",
    ]:

        if receipt.get(
            field
        ) != frozen.get(
            field
        ):

            raise RuntimeError(
                f"Memory receipt {order:03d} mismatch at {field}."
            )


    if receipt[
        "status"
    ] not in FINAL_STATUSES:

        atomic_json(
            FAILURE_MARKER,
            {
                "schema":
                    "stage26_3b_worker_failure_v1",

                "status":
                    "WORKER_FAILURE",

                "memory_execution_order":
                    order,

                "reason":
                    (
                        "Unexpected worker receipt status: "
                        +
                        str(
                            receipt[
                                "status"
                            ]
                        )
                    ),

                "receipt":
                    receipt,
            },
        )

        raise RuntimeError(
            f"Unexpected memory status at {order:03d}."
        )


    if receipt[
        "status"
    ] == "PASS":

        if receipt.get(
            "timing_performed"
        ) is not False:

            raise RuntimeError(
                "Memory worker claims timing was performed."
            )


        if receipt.get(
            "gpu_used"
        ) is not False:

            raise RuntimeError(
                "GPU unexpectedly used in CPU memory profiling."
            )


        if receipt.get(
            "holdout_accessed"
        ) is not False:

            raise RuntimeError(
                "Holdout unexpectedly accessed."
            )


        print(
            f"[PASS] {order:03d}/400 "
            f"baseline={mib(receipt['baseline_rss_bytes']):9.2f} MiB "
            f"loaded={mib(receipt['loaded_rss_bytes']):9.2f} MiB "
            f"peak={mib(receipt['peak_rss_bytes']):10.2f} MiB "
            f"Δmodel={mib(receipt['delta_model_rss_bytes']):8.2f} MiB "
            f"Δpeak={mib(receipt['delta_peak_rss_bytes']):9.2f} MiB",
            flush=True,
        )


    elif receipt[
        "status"
    ] == "RESOURCE_LIMIT_OOM":

        print(
            f"[OOM] {order:03d}/400 "
            f"{target} "
            f"{mode} "
            f"B={batch_size}",
            flush=True,
        )


    elif receipt[
        "status"
    ] == "TIMEOUT_RESOURCE_LIMIT":

        print(
            f"[TIMEOUT] {order:03d}/400 "
            f"{target} "
            f"{mode} "
            f"B={batch_size}",
            flush=True,
        )


    completed_orders.add(
        order
    )


# =============================================================================
# 10. ALL-400 COMPLETENESS GATE
# =============================================================================

banner(
    "STAGE26-3B :: ALL-400 COMPLETENESS GATE"
)


observation_paths = [
    OBS_DIR
    / f"memory_{order:03d}.json"
    for order in range(
        1,
        401,
    )
]


for path in observation_paths:

    if not path.exists():

        raise RuntimeError(
            f"Missing memory observation: {path.name}"
        )


observations = [
    json.loads(
        path.read_text(
            encoding="utf-8"
        )
    )
    for path in observation_paths
]


status_counts = {}


for observation in observations:

    status_counts[
        observation[
            "status"
        ]
    ] = (
        status_counts.get(
            observation[
                "status"
            ],
            0,
        )
        +
        1
    )


print(
    "Status counts:"
)


for key, value in sorted(
    status_counts.items()
):

    print(
        f"  {key:30s}: {value}"
    )


if sum(
    status_counts.values()
) != 400:

    raise RuntimeError(
        "Memory status counts do not sum to 400."
    )


