# =============================================================================

banner(
    "STAGE26-3B :: CONDITION-LEVEL MEMORY SUMMARY"
)


cpu_plan = json.loads(
    CPU_PLAN.read_text(
        encoding="utf-8"
    )
)


source_conditions = sorted(
    cpu_plan[
        "conditions"
    ],
    key=lambda row: int(
        row[
            "execution_order"
        ]
    ),
)


summary_rows = []


for condition in source_conditions:

    source_order = int(
        condition[
            "execution_order"
        ]
    )


    matching = [
        obs
        for obs in observations
        if int(
            obs[
                "source_cpu_execution_order"
            ]
        )
        ==
        source_order
    ]


    if len(
        matching
    ) != 5:

        raise RuntimeError(
            f"CPU condition {source_order:03d} does not have exactly 5 memory reps."
        )


    pass_rows = [
        obs
        for obs in matching
        if obs[
            "status"
        ] == "PASS"
    ]


    condition_status_counts = {}


    for obs in matching:

        condition_status_counts[
            obs[
                "status"
            ]
        ] = (
            condition_status_counts.get(
                obs[
                    "status"
                ],
                0,
            )
            +
            1
        )


    summary = {
        "source_cpu_execution_order":
            source_order,

        "condition_id":
            condition[
                "condition_id"
            ],

        "target_id":
            condition[
                "target_id"
            ],

        "target_role":
            condition[
                "target_role"
            ],

        "comparison_group":
            condition[
                "comparison_group"
            ],

        "hardware_mode":
            condition[
                "hardware_mode"
            ],

        "thread_count":
            int(
                condition[
                    "thread_count"
                ]
            ),

        "batch_size":
            int(
                condition[
                    "batch_size"
                ]
            ),

        "planned_repetitions":
            5,

        "pass_repetitions":
            len(
                pass_rows
            ),

        "resource_limit_oom_repetitions":
            int(
                condition_status_counts.get(
                    "RESOURCE_LIMIT_OOM",
                    0,
                )
            ),

        "timeout_resource_limit_repetitions":
            int(
                condition_status_counts.get(
                    "TIMEOUT_RESOURCE_LIMIT",
                    0,
                )
            ),
    }


    for metric in [
        "baseline_rss_bytes",
        "loaded_rss_bytes",
        "peak_rss_bytes",
        "delta_model_rss_bytes",
        "delta_peak_rss_bytes",
        "ru_maxrss_bytes_descriptive",
    ]:

        values = np.asarray(
            [
                float(
                    obs[
                        metric
                    ]
                )
                for obs in pass_rows
            ],
            dtype=np.float64,
        )


        if values.size:

            summary[
                f"median_{metric}"
            ] = float(
                np.median(
                    values
                )
            )

            summary[
                f"min_{metric}"
            ] = float(
                np.min(
                    values
                )
            )

            summary[
                f"max_{metric}"
            ] = float(
                np.max(
                    values
                )
            )

        else:

            summary[
                f"median_{metric}"
            ] = None

            summary[
                f"min_{metric}"
            ] = None

            summary[
                f"max_{metric}"
            ] = None


    summary_rows.append(
        summary
    )


with SUMMARY_CSV.open(
    "w",
    newline="",
    encoding="utf-8",
) as f:

    writer = csv.DictWriter(
        f,
        fieldnames=list(
            summary_rows[
                0
            ].keys()
        ),
    )

    writer.writeheader()

    writer.writerows(
        summary_rows
    )


