def banner(text):
    print("\n" + "=" * 116)
    print(text)
    print("=" * 116)


def run(cmd, *, cwd=None):
    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(
            "$ "
            + " ".join(map(str, cmd))
            + "\n\n"
            + p.stdout
        )

    return p.stdout.strip()


def git(*args):
    return run(
        ["git", *args],
        cwd=REPO,
    )


def sha256_file(path, *, progress=False):

    path = Path(path)

    h = hashlib.sha256()
    total = 0
    report_step = 2 * 1024**3
    next_report = report_step

    with path.open("rb") as f:

        while True:

            chunk = f.read(
                16 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(chunk)

            total += len(chunk)

            if progress and total >= next_report:

                print(
                    f"  hashed {total / 1024**3:.2f} GiB",
                    flush=True,
                )

                next_report += report_step

    return h.hexdigest()


def atomic_json(path, obj):

    path = Path(path)
    tmp = Path(str(path) + ".tmp")

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write("\n")
        f.flush()
        os.fsync(f.fileno())

    os.replace(tmp, path)


