def banner(text):
    print("\n" + "=" * 116)
    print(text)
    print("=" * 116)


def run(cmd, *, cwd=None, check=False):
    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            "$ "
            + " ".join(map(str, cmd))
            + "\n\n"
            + p.stdout
        )

    return p


def git_repo(*args):
    p = run(
        ["git", *args],
        cwd=REPO,
        check=True,
    )
    return p.stdout.strip()


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        while True:
            chunk = f.read(8 * 1024 * 1024)

            if not chunk:
                break

            h.update(chunk)

    return h.hexdigest()


def atomic_json(path, obj):
    path = Path(path)
    tmp = Path(str(path) + ".tmp")

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write("\n")
        f.flush()
        os.fsync(f.fileno())

    os.replace(tmp, path)


def command_info(name):
    path = shutil.which(name)

    if path is None:
        return {
            "available": False,
            "path": None,
            "version": None,
        }

    outputs = []

    for args in (
        [name, "--version"],
        [name, "-version"],
        [name, "-v"],
    ):

        p = run(args)

        text = (p.stdout or "").strip()

        if text:
            outputs.append(text[:3000])
            break

    return {
        "available": True,
        "path": path,
        "version": outputs[0] if outputs else None,
    }


