def banner(text):

    print(
        "\n"
        + "=" * 112
    )

    print(text)

    print(
        "=" * 112
    )


def human(n):

    n = float(n)

    for unit in [
        "B",
        "KiB",
        "MiB",
        "GiB",
        "TiB",
    ]:

        if n < 1024 or unit == "TiB":

            return f"{n:.3f} {unit}"

        n /= 1024


def sha256_file(
    path,
    *,
    progress=False,
):

    path = Path(path)

    h = hashlib.sha256()

    total = 0

    next_report = (
        2 * 1024**3
    )


    with path.open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                16 * 1024 * 1024
            )

            if not chunk:
                break


            h.update(
                chunk
            )

            total += len(
                chunk
            )


            if (
                progress
                and
                total >= next_report
            ):

                print(
                    f"  hashed "
                    f"{total / 1024**3:.2f} GiB",
                    flush=True,
                )

                next_report += (
                    2 * 1024**3
                )


    return h.hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(path)

    tmp = Path(
        str(path)
        + ".tmp"
    )


    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )


    os.replace(
        tmp,
        path,
    )


def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


