# =============================================================================

def banner(text):

    print(
        "\n"
        + "=" * 118
    )

    print(text)

    print(
        "=" * 118
    )


def human_bytes(n):

    n = float(
        n
    )

    for unit in [
        "B",
        "KiB",
        "MiB",
        "GiB",
        "TiB",
    ]:

        if (
            n < 1024
            or
            unit == "TiB"
        ):

            return (
                f"{n:.3f} {unit}"
            )

        n /= 1024


def sha256_file(
    path,
    *,
    progress=False,
):

    path = Path(
        path
    )

    h = hashlib.sha256()

    total = 0

    next_report = (
        128 * 1024**2
    )


    with path.open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                16 * 1024 * 1024
            )


            if not chunk:
                break


            h.update(
                chunk
            )

            total += len(
                chunk
            )


            if (
                progress
                and
                total >= next_report
            ):

                print(
                    "  hashed",
                    human_bytes(
                        total
                    ),
                    flush=True,
                )

                next_report += (
                    128 * 1024**2
                )


    return h.hexdigest()


def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )


    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )


    return p.stdout.strip()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )


    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )


    os.replace(
        tmp,
        path,
    )


def download_file(
    url,
    destination,
    headers,
):

    destination = Path(
        destination
    )

    partial = Path(
        str(destination)
        + ".part"
    )


    # Resume our own partial HTTP download if one exists.
    existing = (
        partial.stat().st_size
        if partial.exists()
        else 0
    )


    req_headers = dict(
        headers
    )


    if existing > 0:

        req_headers[
            "Range"
        ] = (
            f"bytes={existing}-"
        )


        print(
            "Resuming local release download from:",
            human_bytes(
                existing
            )
        )


    request = urllib.request.Request(
        url,
        headers=req_headers,
        method="GET",
    )


    with urllib.request.urlopen(
        request,
        timeout=300,
    ) as response:

        status_code = int(
            getattr(
                response,
                "status",
                200,
            )
        )


        if (
            existing > 0
            and
            status_code == 206
        ):

            mode = "ab"

        else:

            # Server did not honor Range or there was no partial.
            mode = "wb"

            existing = 0


        downloaded = existing

        next_report = (
            (
                downloaded
                //
                (
                    64 * 1024**2
                )
            )
            +
            1
        ) * (
            64 * 1024**2
        )


        with partial.open(
            mode
        ) as f:

            while True:

                chunk = response.read(
                    8 * 1024 * 1024
                )


                if not chunk:

                    break


                f.write(
                    chunk
                )

                downloaded += len(
                    chunk
                )


                if downloaded >= next_report:

                    print(
                        "  downloaded",
                        human_bytes(
                            downloaded
                        ),
                        flush=True,
                    )

                    next_report += (
                        64 * 1024**2
                    )


            f.flush()

            os.fsync(
                f.fileno()
            )


    os.replace(
        partial,
        destination,
    )


