def banner(text):

    print(
        "\n"
        + "=" * 118
    )

    print(text)

    print(
        "=" * 118
    )


def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(
                chunk
            )

    return h.hexdigest()


def sha256_stream(file_obj):

    h = hashlib.sha256()

    total = 0

    while True:

        chunk = file_obj.read(
            8 * 1024 * 1024
        )

        if not chunk:
            break

        h.update(
            chunk
        )

        total += len(
            chunk
        )

    return (
        h.hexdigest(),
        total,
    )


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def array_summary(
    name,
    arr,
):

    summary = {
        "name":
            name,

        "dtype":
            str(
                arr.dtype
            ),

        "shape":
            list(
                arr.shape
            ),

        "ndim":
            int(
                arr.ndim
            ),

        "size":
            int(
                arr.size
            ),

        "nbytes":
            int(
                arr.nbytes
            ),
    }


    if arr.size > 0:

        summary[
            "min"
        ] = (
            arr.min().item()
        )

        summary[
            "max"
        ] = (
            arr.max().item()
        )

        summary[
            "first_10"
        ] = (
            arr.reshape(
                -1
            )[
                :10
            ].tolist()
        )

        summary[
            "last_10"
        ] = (
            arr.reshape(
                -1
            )[
                -10:
            ].tolist()
        )


    return summary


