# =============================================================================

def banner(text):

    print(
        "\n"
        + "=" * 118
    )

    print(text)

    print(
        "=" * 118
    )


def run(
    cmd,
    *,
    cwd=REPO,
    env=None,
    check=True,
    text=True,
):

    p = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=text,
        check=False,
    )

    if check and p.returncode != 0:

        output = (
            p.stdout
            if text
            else p.stdout.decode(
                "utf-8",
                errors="replace",
            )
        )

        raise RuntimeError(
            "$ "
            + " ".join(
                map(
                    str,
                    cmd,
                )
            )
            + "\n\n"
            + output
        )

    return p


def git(
    *args,
    env=None,
):

    return run(
        [
            "git",
            *args,
        ],
        env=env,
        check=True,
        text=True,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:
                break

            h.update(
                chunk
            )

    return h.hexdigest()


def git_blob_bytes(
    treeish,
    relpath,
):

    p = run(
        [
            "git",
            "show",
            f"{treeish}:{relpath}",
        ],
        check=True,
        text=False,
    )

    return bytes(
        p.stdout
    )


