def banner(text):

    print(
        "\n"
        + "=" * 122
    )

    print(text)

    print(
        "=" * 122
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
):

    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            p.stdout
        )

    return p


def git(*args):

    return run(
        [
            "git",
            *args,
        ]
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            chunk = f.read(
                8 * 1024 * 1024
            )

            if not chunk:

                break

            h.update(
                chunk
            )

    return h.hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def median(values):

    return float(
        statistics.median(
            values
        )
    )


def env_gate():

    attempts = []


    for attempt in range(
        1,
        ENV_GATE_ATTEMPTS + 1,
    ):

        # Sample system utilization for the exact frozen interval.
        cpu_util = float(
            psutil.cpu_percent(
                interval=CPU_SAMPLE_SECONDS
            )
        )


        vm = psutil.virtual_memory()

        available_gib = (
            float(
                vm.available
            )
            /
            1024**3
        )


        cpu_pass = (
            cpu_util
            <=
            MAX_CPU_UTIL_PERCENT
        )

        ram_pass = (
            available_gib
            >=
            MIN_AVAILABLE_RAM_GIB
        )


        attempt_record = {
            "attempt":
                attempt,

            "cpu_utilization_percent":
                cpu_util,

            "available_ram_gib":
                available_gib,

            "cpu_gate_pass":
                cpu_pass,

            "ram_gate_pass":
                ram_pass,

            "gate_pass":
                (
                    cpu_pass
                    and
                    ram_pass
                ),
        }


        attempts.append(
            attempt_record
        )


        print(
            f"  gate attempt {attempt}/{ENV_GATE_ATTEMPTS}: "
            f"CPU={cpu_util:.1f}% "
            f"(<= {MAX_CPU_UTIL_PERCENT:.1f}%) | "
            f"RAM={available_gib:.3f} GiB "
            f"(>= {MIN_AVAILABLE_RAM_GIB:.1f}) | "
            f"{'PASS' if attempt_record['gate_pass'] else 'RETRY'}"
        )


        if attempt_record[
            "gate_pass"
        ]:

            return (
                True,
                attempts,
            )


        if attempt < ENV_GATE_ATTEMPTS:

            time.sleep(
                ENV_GATE_RETRY_SECONDS
            )


    return (
        False,
        attempts,
    )


