def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def human_bytes(n):

    n = float(
        n
    )

    for unit in [
        "B",
        "KiB",
        "MiB",
        "GiB",
    ]:

        if n < 1024 or unit == "GiB":

            return (
                f"{n:.3f} {unit}"
            )

        n /= 1024


