# =============================================================================
# 6. RESTORE EXACT RELEASE TAR
# =============================================================================

banner(
    "STAGE26-4C0-RECOVERY :: RESTORE MONDAY RELEASE ASSET"
)


if MONDAY_TAR.exists():

    print(
        "Existing candidate TAR found."
    )

    print(
        "Verifying rather than downloading."
    )


    existing_size = int(
        MONDAY_TAR.stat().st_size
    )


    if existing_size != EXPECTED_TAR_SIZE:

        raise RuntimeError(
            "Existing Monday TAR has wrong size."
        )


    tar_sha = sha256_file(
        MONDAY_TAR
    )


else:

    temp_tar = Path(
        str(
            MONDAY_TAR
        )
        +
        ".download"
    )


    if temp_tar.exists():

        temp_tar.unlink()


    # GitHub asset API with octet-stream performs authenticated asset download.
    asset_download_api = (
        f"https://api.github.com/repos/"
        f"{GITHUB_OWNER}/{GITHUB_REPO}/releases/assets/"
        f"{asset['id']}"
    )


    download_headers = dict(
        headers
    )

    download_headers[
        "Accept"
    ] = "application/octet-stream"


    with requests.get(
        asset_download_api,
        headers=download_headers,
        stream=True,
        timeout=120,
        allow_redirects=True,
    ) as r:

        if r.status_code != 200:

            raise RuntimeError(
                "Monday Release download failed:\n"
                f"HTTP {r.status_code}\n"
                f"{r.text[:1000]}"
            )


        h = hashlib.sha256()

        total = 0

        next_progress = (
            128 * 1024 * 1024
        )


        with temp_tar.open(
            "wb"
        ) as f:

            for chunk in r.iter_content(
                chunk_size=8 * 1024 * 1024
            ):

                if not chunk:

                    continue

                f.write(
                    chunk
                )

                h.update(
                    chunk
                )

                total += len(
                    chunk
                )


                if total >= next_progress:

                    print(
                        "  restored:",
                        human_bytes(
                            total
                        )
                    )

                    next_progress += (
                        128 * 1024 * 1024
                    )


            f.flush()

            os.fsync(
                f.fileno()
            )


    tar_sha = h.hexdigest()


    if total != EXPECTED_TAR_SIZE:

        raise RuntimeError(
            f"Downloaded size mismatch: {total}"
        )


    if tar_sha != EXPECTED_TAR_SHA256:

        raise RuntimeError(
            "Downloaded Monday TAR SHA256 mismatch."
        )


    os.replace(
        temp_tar,
        MONDAY_TAR,
    )


