# =============================================================================
# 7. VERIFY ALL FOUR TAR MEMBERS
# =============================================================================

banner(
    "STAGE26-4C0-RECOVERY :: TAR MEMBER BYTE VERIFICATION"
)


member_records = {}

array_payloads = {}


with tarfile.open(
    MONDAY_TAR,
    mode="r:",
) as tf:

    files = {
        member.name:
            member
        for member in tf.getmembers()
        if member.isfile()
    }


    if set(
        files
    ) != set(
        EXPECTED_MEMBERS
    ):

        print(
            "Expected members:"
        )

        for x in sorted(
            EXPECTED_MEMBERS
        ):

            print(
                " ",
                x
            )


        print(
            "\nActual members:"
        )

        for x in sorted(
            files
        ):

            print(
                " ",
                x
            )


        raise RuntimeError(
            "Monday TAR member set changed."
        )


    for member_name, frozen in EXPECTED_MEMBERS.items():

        member = files[
            member_name
        ]


        if int(
            member.size
        ) != int(
            frozen[
                "size"
            ]
        ):

            raise RuntimeError(
                f"Member size mismatch: {member_name}"
            )


        fileobj = tf.extractfile(
            member
        )


        if fileobj is None:

            raise RuntimeError(
                f"Could not read TAR member: {member_name}"
            )


        h = hashlib.sha256()

        total = 0

        chunks_for_array = (
            []
            if member_name.endswith(
                ".npy"
            )
            else None
        )


        while True:

            block = fileobj.read(
                8 * 1024 * 1024
            )

            if not block:

                break

            h.update(
                block
            )

            total += len(
                block
            )


            if chunks_for_array is not None:

                chunks_for_array.append(
                    block
                )


        digest = h.hexdigest()


        passed = (
            total
            ==
            int(
                frozen[
                    "size"
                ]
            )
            and
            digest
            ==
            frozen[
                "sha256"
            ]
        )


        print(
            f"{member_name:34s} "
            f"{'PASS' if passed else 'FAIL'} "
            f"{total:12,d} B "
            f"{digest}"
        )


        if not passed:

            raise RuntimeError(
                f"Release member identity failed: {member_name}"
            )


        member_records[
            member_name
        ] = {
            "size_bytes":
                total,

            "sha256":
                digest,
        }


        if chunks_for_array is not None:

            array_payloads[
                member_name
            ] = b"".join(
                chunks_for_array
            )


