def resolve_named_integer(
    preferred_names,
    expected_value,
):

    matches = []


    # First: exact preferred names.
    for name in preferred_names:

        info = module_assignments.get(
            name
        )

        if (
            info is not None
            and
            info[
                "literal_ok"
            ]
            and
            isinstance(
                info[
                    "literal_value"
                ],
                int,
            )
            and
            int(
                info[
                    "literal_value"
                ]
            )
            ==
            expected_value
        ):

            matches.append(
                {
                    "name":
                        name,

                    **info,
                }
            )


    if matches:

        return matches[
            0
        ]


    # Second: semantic fallback among packet/byte-related module constants.
    for name, info in interesting.items():

        if not info[
            "literal_ok"
        ]:

            continue


        value = info[
            "literal_value"
        ]


        if (
            isinstance(
                value,
                int,
            )
            and
            int(
                value
            )
            ==
            expected_value
        ):

            matches.append(
                {
                    "name":
                        name,

                    **info,
                }
            )


    if len(
        matches
    ) == 1:

        return matches[
            0
        ]


    print(
        f"\nCould not uniquely resolve expected integer {expected_value}."
    )

    print(
        "Candidate matches:"
    )


    for item in matches:

        print(
            " ",
            item
        )


    raise RuntimeError(
        f"Could not uniquely resolve frozen encoder constant {expected_value}."
    )


