    # np.float32 or bare float32
    if isinstance(
        node,
        ast.Attribute,
    ):

        if node.attr == "float32":

            has_float32 = True


    elif isinstance(
        node,
        ast.Name,
    ):

        if node.id == "float32":

            has_float32 = True


    if isinstance(
        node,
        ast.BinOp,
    ) and isinstance(
        node.op,
        ast.Div,
    ):

        try:

            divisor = ast.literal_eval(
                node.right
            )

            if float(
                divisor
            ) == 255.0:

                has_255_division = True

        except Exception:

            pass


