def banner(text):

    print(
        "\n"
        + "=" * 122
    )

    print(text)

    print(
        "=" * 122
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
):

    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            p.stdout
        )

    return p


def git(*args):

    return run(
        [
            "git",
            *args,
        ]
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def sha256_bytes(data):

    return hashlib.sha256(
        data
    ).hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def source_segment(
    source,
    node,
):

    value = ast.get_source_segment(
        source,
        node,
    )

    return (
        value
        if value is not None
        else "<source unavailable>"
    )


def numeric_semantic_value(node):
    """
    Resolve only deliberately-safe numeric AST forms required for provenance:
      255
      255.0
      +255.0
      -255.0
      np.float32(255.0)
      float32(255.0)
      float(255.0)
      int(255)
    """

    if isinstance(
        node,
        ast.Constant,
    ):

        if isinstance(
            node.value,
            (
                int,
                float,
            ),
        ):

            return float(
                node.value
            )


    if isinstance(
        node,
        ast.UnaryOp,
    ):

        value = numeric_semantic_value(
            node.operand
        )

        if value is None:

            return None


        if isinstance(
            node.op,
            ast.UAdd,
        ):

            return value


        if isinstance(
            node.op,
            ast.USub,
        ):

            return -value


    if isinstance(
        node,
        ast.Call,
    ):

        if (
            len(
                node.args
            )
            != 1
            or
            node.keywords
        ):

            return None


        constructor = None


        if isinstance(
            node.func,
            ast.Name,
        ):

            constructor = node.func.id


        elif isinstance(
            node.func,
            ast.Attribute,
        ):

            constructor = node.func.attr


        if constructor not in {
            "float",
            "int",
            "float16",
            "float32",
            "float64",
            "int16",
            "int32",
            "int64",
            "uint16",
            "uint32",
            "uint64",
        }:

            return None


        return numeric_semantic_value(
            node.args[
                0
            ]
        )


    return None


