# Static import audit.
worker_tree = ast.parse(
    WORKER_TEXT
)


import_roots = set()


for node in ast.walk(
    worker_tree
):

    if isinstance(
        node,
        ast.Import,
    ):

        for alias in node.names:

            import_roots.add(
                alias.name.split(
                    "."
                )[
                    0
                ]
            )


    elif isinstance(
        node,
        ast.ImportFrom,
    ):

        if node.module:

            import_roots.add(
                node.module.split(
                    "."
                )[
                    0
                ]
            )


for forbidden_module in {
    "scapy",
    "dpkt",
    "pyshark",
    "torch",
}:

    if forbidden_module in import_roots:

        raise RuntimeError(
            f"Forbidden worker import: {forbidden_module}"
        )


if (
    '"labels.npy"' in WORKER_TEXT
    or
    "'labels.npy'" in WORKER_TEXT
):

    raise RuntimeError(
        "Representation worker constructs or names labels.npy."
    )


