def banner(text):

    print(
        "\n"
        + "=" * 122
    )

    print(text)

    print(
        "=" * 122
    )


def run(
    cmd,
    *,
    cwd=REPO,
    env=None,
    check=True,
    text=True,
):

    p = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=text,
        check=False,
    )

    if check and p.returncode != 0:

        output = (
            p.stdout
            if text
            else
            p.stdout.decode(
                "utf-8",
                errors="replace",
            )
        )

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            output
        )

    return p


def git(
    *args,
    env=None,
):

    return run(
        [
            "git",
            *args,
        ],
        env=env,
        check=True,
        text=True,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def sha256_bytes(data):

    return hashlib.sha256(
        data
    ).hexdigest()


def atomic_text(
    path,
    text,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        f.write(
            text
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def atomic_json(
    path,
    obj,
):

    atomic_text(
        path,
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
        )
        +
        "\n",
    )


def source_segment(
    source,
    node,
):

    value = ast.get_source_segment(
        source,
        node,
    )

    return (
        value
        if value is not None
        else "<source unavailable>"
    )


def git_blob_bytes(
    treeish,
    repo_relative_path,
):

    result = run(
        [
            "git",
            "show",
            f"{treeish}:{repo_relative_path}",
        ],
        check=True,
        text=False,
    )

    return bytes(
        result.stdout
    )


def call_name(node):

    if isinstance(
        node,
        ast.Name,
    ):

        return node.id


    if isinstance(
        node,
        ast.Attribute,
    ):

        left = call_name(
            node.value
        )

        if left:

            return (
                left
                +
                "."
                +
                node.attr
            )

        return node.attr


    return None


def resolve_shape(node):

    if isinstance(
        node,
        ast.Name,
    ):

        if node.id == "ROWS":
            return [64]

        if node.id == "COLS":
            return [256]


    if isinstance(
        node,
        ast.Constant,
    ) and isinstance(
        node.value,
        int,
    ):

        return [
            int(
                node.value
            )
        ]


    if isinstance(
        node,
        (
            ast.Tuple,
            ast.List,
        ),
    ):

        result = []


        for element in node.elts:

            if isinstance(
                element,
                ast.Name,
            ):

                if element.id == "ROWS":

                    result.append(
                        64
                    )

                elif element.id == "COLS":

                    result.append(
                        256
                    )

                else:

                    return None


            elif isinstance(
                element,
                ast.Constant,
            ) and isinstance(
                element.value,
                int,
            ):

                result.append(
                    int(
                        element.value
                    )
                )


            else:

                return None


        return result


    return None


def resolve_dtype(call):

    if not isinstance(
        call,
        ast.Call,
    ):

        return None


    for keyword in call.keywords:

        if keyword.arg != "dtype":
            continue

        return call_name(
            keyword.value
        )


    return None


