from kaggle_secrets import UserSecretsClient


github_token = UserSecretsClient().get_secret(
    "GITHUB_TOKEN"
)


if not github_token:

    raise RuntimeError(
        "Kaggle secret GITHUB_TOKEN unavailable."
    )


print(
    "GITHUB_TOKEN: FOUND"
)

print(
    "Token value : <not printed>"
)


with tempfile.TemporaryDirectory(
    prefix="stage26_git_auth_"
) as tmpdir:

    tmpdir = Path(
        tmpdir
    )

    askpass = (
        tmpdir
        / "askpass.sh"
    )


    askpass.write_text(
        """#!/bin/sh
case "$1" in
  *sername*) printf '%s\\n' "x-access-token" ;;
  *assword*) printf '%s\\n' "$STAGE26_GITHUB_TOKEN" ;;
  *) printf '%s\\n' "" ;;
esac
""",
        encoding="utf-8",
    )


    askpass.chmod(
        askpass.stat().st_mode
        |
        stat.S_IXUSR
    )


    push_env = os.environ.copy()

    push_env[
        "GIT_ASKPASS"
    ] = str(
        askpass
    )

    push_env[
        "GIT_TERMINAL_PROMPT"
    ] = "0"

    push_env[
        "STAGE26_GITHUB_TOKEN"
    ] = github_token


    pushed = run(
        [
            "git",
            "push",
            "origin",
            "main",
        ],
        env=push_env,
        check=True,
        text=True,
    )


    print(
        pushed.stdout.strip()
    )


github_token = None


