CORPUS_RUNTIME_DIR.mkdir(
    parents=True,
    exist_ok=False,
)


restored_members = []


with tarfile.open(
    MONDAY_TAR,
    mode="r:",
) as tf:

    tar_members = {
        member.name:
            member
        for member in tf.getmembers()
        if member.isfile()
    }


    # labels.npy may exist in TAR, but must never be extracted/opened.
    if FORBIDDEN_TAR_MEMBER not in tar_members:

        raise RuntimeError(
            "Expected authoritative labels TAR member not present; "
            "source structure unexpectedly changed."
        )


    for output_name, frozen in REQUIRED_MEMBERS.items():

        tar_member_name = frozen[
            "tar_member"
        ]


        if tar_member_name not in tar_members:

            raise RuntimeError(
                f"Required Release member missing: {tar_member_name}"
            )


        member = tar_members[
            tar_member_name
        ]


        if int(
            member.size
        ) != int(
            frozen[
                "size_bytes"
            ]
        ):

            raise RuntimeError(
                f"TAR member size mismatch: {tar_member_name}"
            )


        source = tf.extractfile(
            member
        )


        if source is None:

            raise RuntimeError(
                f"Could not open TAR member: {tar_member_name}"
            )


        destination = (
            CORPUS_RUNTIME_DIR
            / output_name
        )


        h = hashlib.sha256()

        total = 0


        with destination.open(
            "wb"
        ) as dst:

            while True:

                block = source.read(
                    8 * 1024 * 1024
                )

                if not block:
                    break

                dst.write(
                    block
                )

                h.update(
                    block
                )

                total += len(
                    block
                )


            dst.flush()

            os.fsync(
                dst.fileno()
            )


        digest = h.hexdigest()


        passed = (
            total
            ==
            int(
                frozen[
                    "size_bytes"
                ]
            )
            and
            digest
            ==
            frozen[
                "sha256"
            ]
        )


        print(
            f"{output_name:22s} "
            f"{'PASS' if passed else 'FAIL'} "
            f"{total:12,d} B "
            f"{digest}"
        )


        if not passed:

            raise RuntimeError(
                f"Restored member verification failed: {output_name}"
            )


        restored_members.append(
            {
                "runtime_filename":
                    output_name,

                "source_tar_member":
                    tar_member_name,

                "size_bytes":
                    total,

                "sha256":
                    digest,
            }
        )


