def banner(text):

    print(
        "\n"
        + "=" * 122
    )

    print(text)

    print(
        "=" * 122
    )


def run(
    cmd,
    *,
    cwd=REPO,
    env=None,
    check=True,
    text=True,
    timeout=None,
):

    p = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=text,
        check=False,
        timeout=timeout,
    )

    if check and p.returncode != 0:

        output = (
            p.stdout
            if text
            else
            p.stdout.decode(
                "utf-8",
                errors="replace",
            )
        )

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            output
        )

    return p


def git(
    *args,
    env=None,
):

    return run(
        [
            "git",
            *args,
        ],
        env=env,
        check=True,
        text=True,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def sha256_bytes(data):

    return hashlib.sha256(
        data
    ).hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def git_blob_bytes(
    treeish,
    repo_relative_path,
):

    p = run(
        [
            "git",
            "show",
            f"{treeish}:{repo_relative_path}",
        ],
        check=True,
        text=False,
    )

    return bytes(
        p.stdout
    )


def percentile(
    values,
    q,
):

    values = np.asarray(
        values,
        dtype=np.float64,
    )

    return float(
        np.percentile(
            values,
            q,
            method="linear",
        )
    )


def environment_gate():

    attempts = []


    for attempt in range(
        1,
        ENVIRONMENT_GATE[
            "retry_count"
        ]
        +
        1,
    ):

        cpu_percent = float(
            psutil.cpu_percent(
                interval=ENVIRONMENT_GATE[
                    "cpu_utilization_sampling_seconds"
                ]
            )
        )

        available_ram_gib = float(
            psutil.virtual_memory().available
            /
            (
                1024
                **
                3
            )
        )

        passed = (
            cpu_percent
            <=
            ENVIRONMENT_GATE[
                "cpu_utilization_percent_max"
            ]
            and
            available_ram_gib
            >=
            ENVIRONMENT_GATE[
                "available_ram_gib_min"
            ]
        )


        record = {
            "attempt":
                attempt,

            "cpu_utilization_percent":
                cpu_percent,

            "available_ram_gib":
                available_ram_gib,

            "passed":
                passed,
        }


        attempts.append(
            record
        )


        print(
            f"  gate attempt {attempt}: "
            f"CPU={cpu_percent:.1f}% "
            f"RAM={available_ram_gib:.3f} GiB "
            f"{'PASS' if passed else 'FAIL'}"
        )


        if passed:

            return {
                "status":
                    "PASS",

                "successful_attempt":
                    attempt,

                "attempts":
                    attempts,
            }


        if (
            attempt
            <
            ENVIRONMENT_GATE[
                "retry_count"
            ]
        ):

            time.sleep(
                ENVIRONMENT_GATE[
                    "retry_cooldown_seconds"
                ]
            )


    return {
        "status":
            "INVALID_ENVIRONMENT",

        "successful_attempt":
            None,

        "attempts":
            attempts,
    }


