# =============================================================================

banner(
    "STAGE26-4C3 :: WRITE RAW OBSERVATIONS"
)


raw_fieldnames = [
    "condition_index",
    "batch_size",
    "iteration_index",
    "elapsed_ns",
    "elapsed_seconds",
    "flows",
    "flows_per_second",
    "image_output_bytes",
    "padding_mask_output_bytes",
    "total_output_bytes",
]


with RAW_CSV_PATH.open(
    "w",
    encoding="utf-8",
    newline="",
) as f:

    writer = csv.DictWriter(
        f,
        fieldnames=raw_fieldnames,
    )

    writer.writeheader()

    writer.writerows(
        raw_observation_rows
    )


raw_csv_sha = sha256_file(
    RAW_CSV_PATH
)


expected_raw_count = sum(
    ITERATION_POLICY[
        batch
    ][
        "timed_runs"
    ]
    for batch in BATCH_SIZES
)


if len(
    raw_observation_rows
) != expected_raw_count:

    raise RuntimeError(
        "Unexpected total raw observation count."
    )


print(
    "Raw observations:",
    len(
        raw_observation_rows
    )
)

print(
    "Expected        :",
    expected_raw_count
)

print(
    "Raw CSV SHA256 :",
    raw_csv_sha
)


