def banner(text):

    print(
        "\n"
        +
        "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
):

    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            p.stdout
        )

    return p.stdout.strip()


def git(
    *args,
):

    return run(
        [
            "git",
            *args,
        ]
    )


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8
                *
                1024
                *
                1024
            )

            if not block:

                break

            h.update(
                block
            )

    return h.hexdigest()


def safe_text(path):

    path = Path(
        path
    )

    if not path.is_file():

        return None

    if path.suffix.lower() not in TEXT_SUFFIXES:

        return None

    if path.stat().st_size > MAX_TEXT_BYTES:

        return None

    try:

        return path.read_text(
            encoding="utf-8",
            errors="replace",
        )

    except Exception:

        return None


def normalize(value):

    return re.sub(
        r"[^a-z0-9]+",
        "",
        str(
            value
        ).lower(),
    )


def alias_hit(
    text,
    aliases,
):

    text_lower = text.lower()

    hits = []

    for alias in aliases:

        if alias.lower() in text_lower:

            hits.append(
                alias
            )

    return hits


def json_walk(
    obj,
    path="$",
):

    if isinstance(
        obj,
        dict,
    ):

        yield (
            path,
            obj,
        )

        for key, value in obj.items():

            child = (
                path
                +
                "."
                +
                str(
                    key
                )
            )

            yield from json_walk(
                value,
                child,
            )


    elif isinstance(
        obj,
        list,
    ):

        for index, value in enumerate(
            obj
        ):

            child = (
                path
                +
                f"[{index}]"
            )

            yield from json_walk(
                value,
                child,
            )


def scalar_metric_pairs(
    obj,
):

    pairs = []

    if not isinstance(
        obj,
        dict,
    ):

        return pairs

    for key, value in obj.items():

        if isinstance(
            value,
            (
                str,
                int,
                float,
                bool,
            )
        ) or value is None:

            pairs.append(
                (
                    str(
                        key
                    ),
                    value,
                )
            )

    return pairs


def compact_dict(
    obj,
    max_items=18,
):

    if not isinstance(
        obj,
        dict,
    ):

        return obj

    result = {}

    for index, (
        key,
        value,
    ) in enumerate(
        obj.items()
    ):

        if index >= max_items:

            result[
                "...truncated..."
            ] = (
                len(
                    obj
                )
                -
                max_items
            )

            break

        if isinstance(
            value,
            (
                str,
                int,
                float,
                bool,
            )
        ) or value is None:

            result[
                str(
                    key
                )
            ] = value

    return result


def line_evidence(
    text,
    aliases,
    require_regex=None,
    max_lines=8,
):

    evidence = []

    for line_number, line in enumerate(
        text.splitlines(),
        start=1,
    ):

        if not alias_hit(
            line,
            aliases,
        ):

            continue

        if (
            require_regex is not None
            and
            not require_regex.search(
                line
            )
        ):

            continue

        evidence.append(
            {
                "line":
                    line_number,

                "text":
                    line[
                        :1000
                    ],
            }
        )

        if len(
            evidence
        ) >= max_lines:

            break

    return evidence


