# =============================================================================
# 8. STAGE26-2 CPU1 B=1 P95 COST SOURCE DISCOVERY
# =============================================================================

banner(
    "STAGE26-6A :: CPU1 B=1 P95 INFERENCE-COST SOURCE CANDIDATES"
)


cost_candidates = {
    target_id: []
    for target_id in PRIMARY_TARGETS
}


for rel in warm_paths:

    path = (
        REPO
        /
        rel
    )

    text = safe_text(
        path
    )


    if text is None:

        continue


    # Cheap file-level prefilter.
    if not (
        P95_REGEX.search(
            text
        )
        or
        "p95" in text.lower()
    ):

        continue


    file_sha = sha256_file(
        path
    )


    for target_id, metadata in PRIMARY_TARGETS.items():

        aliases = [
            target_id,
            *metadata[
                "aliases"
            ],
        ]


        if not alias_hit(
            text,
            aliases,
        ):

            continue


        record = {
            "repo_relative_path":
                rel,

            "sha256":
                file_sha,

            "size_bytes":
                int(
                    path.stat().st_size
                ),

            "aliases_matched":
                sorted(
                    set(
                        alias_hit(
                            text,
                            aliases,
                        )
                    )
                ),

            "structured_cost_evidence":
                [],

            "line_evidence":
                [],
        }


        # -------------------------------------------------------------
        # JSON
        # -------------------------------------------------------------

        if path.suffix.lower() == ".json":

            try:

                obj = json.loads(
                    text
                )

            except Exception:

                obj = None


            if obj is not None:

                for node_path, node in json_walk(
                    obj
                ):

                    if not isinstance(
                        node,
                        dict,
                    ):

                        continue


                    node_text = json.dumps(
                        node,
                        default=str,
                    )


                    if not alias_hit(
                        node_text,
                        aliases,
                    ):

                        continue


                    scalar = dict(
                        scalar_metric_pairs(
                            node
                        )
                    )


                    p95_pairs = [
                        (
                            key,
                            value,
                        )
                        for key, value in scalar.items()
                        if (
                            P95_REGEX.search(
                                key
                            )
                            or
                            (
                                "95"
                                in
                                normalize(
                                    key
                                )
                                and
                                LATENCY_REGEX.search(
                                    key
                                )
                            )
                        )
                    ]


                    if not p95_pairs:

                        continue


                    # Record candidate context. Do NOT silently choose it.
                    record[
                        "structured_cost_evidence"
                    ].append(
                        {
                            "json_path":
                                node_path,

                            "p95_pairs":
                                p95_pairs,

                            "context":
                                compact_dict(
                                    node,
                                    max_items=30,
                                ),
                        }
                    )


                    if len(
                        record[
                            "structured_cost_evidence"
                        ]
                    ) >= 15:

                        break


        # -------------------------------------------------------------
        # CSV
        # -------------------------------------------------------------

        elif path.suffix.lower() == ".csv":

            try:

                reader = csv.DictReader(
                    io.StringIO(
                        text
                    )
                )

                fieldnames = (
                    reader.fieldnames
                    or
                    []
                )


                p95_columns = [
                    column
                    for column in fieldnames
                    if (
                        P95_REGEX.search(
                            str(
                                column
                            )
                        )
                        or
                        (
                            "95"
                            in
                            normalize(
                                column
                            )
                            and
                            LATENCY_REGEX.search(
                                str(
                                    column
                                )
                            )
                        )
                    )
                ]


                if p95_columns:

                    for row_number, row in enumerate(
                        reader,
                        start=2,
                    ):

                        row_text = " | ".join(
                            f"{k}={v}"
                            for k, v in row.items()
                        )


                        if not alias_hit(
                            row_text,
                            aliases,
                        ):

                            continue


                        # Keep explicit batch/mode fields in context so
                        # CPU1/B1 can be resolved from output.
                        context = {
                            key:
                                value
                            for key, value in row.items()
                            if (
                                value not in {
                                    None,
                                    "",
                                }
                                and
                                (
                                    key in p95_columns
                                    or
                                    re.search(
                                        r"(?i)"
                                        r"(target|model|batch|cpu|mode|"
                                        r"affinity|thread|latency|status|"
                                        r"condition)",
                                        str(
                                            key
                                        ),
                                    )
                                )
                            )
                        }


                        record[
                            "structured_cost_evidence"
                        ].append(
                            {
                                "csv_row":
                                    row_number,

                                "p95_pairs": [
                                    (
                                        column,
                                        row.get(
                                            column
                                        ),
                                    )
                                    for column in p95_columns
                                ],

                                "context":
                                    context,
                            }
                        )


                        if len(
                            record[
                                "structured_cost_evidence"
                            ]
                        ) >= 15:

                            break

            except Exception:

                pass


        # -------------------------------------------------------------
        # Plain line evidence
        # -------------------------------------------------------------

        for line_number, line in enumerate(
            text.splitlines(),
            start=1,
        ):

            if not alias_hit(
                line,
                aliases,
            ):

                continue

            if not P95_REGEX.search(
                line
            ):

                continue


            record[
                "line_evidence"
            ].append(
                {
                    "line":
                        line_number,

                    "text":
                        line[
                            :1200
                        ],
                }
            )


            if len(
                record[
                    "line_evidence"
                ]
            ) >= 8:

                break


        if (
            record[
                "structured_cost_evidence"
            ]
            or
            record[
                "line_evidence"
            ]
        ):

            cost_candidates[
                target_id
            ].append(
                record
            )


