def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    env=None,
    check=True,
    text=True,
):

    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=text,
        check=False,
    )

    if check and p.returncode != 0:

        output = (
            p.stdout
            if text
            else
            p.stdout.decode(
                "utf-8",
                errors="replace",
            )
        )

        raise RuntimeError(
            "$ "
            + " ".join(
                map(
                    str,
                    cmd,
                )
            )
            + "\n\n"
            + output
        )

    return p


def git(
    *args,
    env=None,
):

    return run(
        [
            "git",
            *args,
        ],
        env=env,
        text=True,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def sha256_bytes(data):

    return hashlib.sha256(
        data
    ).hexdigest()


def atomic_json(
    path,
    obj,
):

    path = Path(
        path
    )

    tmp = Path(
        str(path) + ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def git_blob_bytes(
    treeish,
    repo_relative_path,
):

    p = run(
        [
            "git",
            "show",
            f"{treeish}:{repo_relative_path}",
        ],
        text=False,
    )

    return bytes(
        p.stdout
    )


def dominates(
    point_a,
    point_b,
):

    pr_a = float(
        point_a[
            "pr_auc"
        ]
    )

    pr_b = float(
        point_b[
            "pr_auc"
        ]
    )

    latency_a = float(
        point_a[
            "p95_cpu1_batch1_inference_latency_ms"
        ]
    )

    latency_b = float(
        point_b[
            "p95_cpu1_batch1_inference_latency_ms"
        ]
    )

    no_worse_discrimination = (
        pr_a >= pr_b
    )

    no_worse_latency = (
        latency_a <= latency_b
    )

    at_least_one_strict = (
        pr_a > pr_b
        or
        latency_a < latency_b
    )

    return (
        no_worse_discrimination
        and
        no_worse_latency
        and
        at_least_one_strict
    )


