def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
    text=True,
):

    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=text,
        check=False,
    )

    if check and p.returncode != 0:

        output = (
            p.stdout
            if text
            else
            p.stdout.decode(
                "utf-8",
                errors="replace",
            )
        )

        raise RuntimeError(
            "$ "
            + " ".join(
                map(
                    str,
                    cmd,
                )
            )
            + "\n\n"
            + output
        )

    return p


def git(
    *args,
):

    return run(
        [
            "git",
            *args,
        ],
        text=True,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def load_csv(
    path,
):

    with Path(path).open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:

        return list(
            csv.DictReader(
                f
            )
        )


def unique(
    values,
):

    return sorted(
        set(
            values
        )
    )


def recursive_key_evidence(
    obj,
    *,
    path="$",
    predicate,
    out=None,
):

    if out is None:
        out = []


    if isinstance(
        obj,
        dict,
    ):

        for key, value in obj.items():

            child = (
                path
                + "."
                + str(
                    key
                )
            )


            if predicate(
                str(
                    key
                ),
                value,
            ):

                out.append(
                    {
                        "path":
                            child,

                        "value":
                            value,
                    }
                )


            recursive_key_evidence(
                value,
                path=child,
                predicate=predicate,
                out=out,
            )


    elif isinstance(
        obj,
        list,
    ):

        for index, value in enumerate(
            obj
        ):

            recursive_key_evidence(
                value,
                path=(
                    path
                    +
                    f"[{index}]"
                ),
                predicate=predicate,
                out=out,
            )


    return out


def strict_pr_auc_uncertainty_key(
    key,
    value,
):

    k = key.lower()


    has_pr = (
        "pr_auc" in k
        or
        "prauc" in k
        or
        "auprc" in k
        or
        "average_precision" in k
    )


    has_uncertainty = any(
        token in k
        for token in [
            "ci",
            "confidence",
            "bootstrap",
            "lower",
            "upper",
            "low",
            "high",
            "std",
            "stderr",
            "standard_error",
        ]
    )


    return (
        has_pr
        and
        has_uncertainty
    )


def generic_uncertainty_key(
    key,
    value,
):

    k = key.lower()

    return any(
        token in k
        for token in [
            "bootstrap",
            "confidence",
            "ci95",
            "ci_95",
            "lower",
            "upper",
            "stderr",
            "standard_error",
        ]
    )


