summary_rows = load_csv(
    WARM_SUMMARY
)


# =============================================================================
# 5. EXACT P95 SEMANTICS AUDIT
# =============================================================================

banner(
    "STAGE26-6E-DIAG :: EXACT P95 COMPUTATION PATHS"
)


path_match_counts = {
    "percentile_ns_then_divide":
        0,

    "percentile_ms":
        0,

    "quantile_ns_then_divide":
        0,

    "quantile_ms":
        0,
}


per_target = {}


for target, condition_id in PRIMARY_CONDITIONS.items():

    raw_matches = [
        row
        for row in raw_rows
        if (
            row[
                "target_id"
            ]
            ==
            target
            and
            row[
                "condition_id"
            ]
            ==
            condition_id
        )
    ]


    summary_matches = [
        row
        for row in summary_rows
        if (
            row[
                "target_id"
            ]
            ==
            target
            and
            row[
                "condition_id"
            ]
            ==
            condition_id
            and
            row[
                "hardware_mode"
            ]
            ==
            "CPU_1_PHYSICAL_CORE"
            and
            int(
                row[
                    "batch_size"
                ]
            )
            ==
            1
        )
    ]


    if len(
        raw_matches
    ) != 200:

        raise RuntimeError(
            f"{target}: expected 200 raw observations."
        )


    if len(
        summary_matches
    ) != 1:

        raise RuntimeError(
            f"{target}: expected exactly one summary row."
        )


    elapsed_ns_int = np.asarray(
        [
            int(
                row[
                    "elapsed_ns"
                ]
            )
            for row in raw_matches
        ],
        dtype=np.int64,
    )


    elapsed_ns_float = elapsed_ns_int.astype(
        np.float64
    )

    elapsed_ms = (
        elapsed_ns_float
        /
        1_000_000.0
    )


    stored = float(
        summary_matches[
            0
        ][
            "p95_batch_latency_ms"
        ]
    )


    # -------------------------------------------------------------
    # Candidate A:
    # percentile in nanoseconds, divide returned scalar afterward
    # -------------------------------------------------------------

    a = (
        np.percentile(
            elapsed_ns_int,
            95,
            method="linear",
        )
        /
        1_000_000.0
    )


    # -------------------------------------------------------------
    # Candidate B:
    # convert every observation to ms first, then percentile
    # -------------------------------------------------------------

    b = np.percentile(
        elapsed_ms,
        95,
        method="linear",
    )


    # -------------------------------------------------------------
    # Candidate C:
    # quantile in ns, divide scalar afterward
    # -------------------------------------------------------------

    c = (
        np.quantile(
            elapsed_ns_int,
            0.95,
            method="linear",
        )
        /
        1_000_000.0
    )


    # -------------------------------------------------------------
    # Candidate D:
    # convert every observation to ms first, then quantile
    # -------------------------------------------------------------

    d = np.quantile(
        elapsed_ms,
        0.95,
        method="linear",
    )


    candidates = {
        "percentile_ns_then_divide":
            float(
                a
            ),

        "percentile_ms":
            float(
                b
            ),

        "quantile_ns_then_divide":
            float(
                c
            ),

        "quantile_ms":
            float(
                d
            ),
    }


    print(
        "\n",
        target,
        sep="",
    )

    print(
        "  condition:",
        condition_id
    )

    print(
        "  stored repr:",
        repr(
            stored
        )
    )

    print(
        "  stored hex :",
        stored.hex()
    )


    for name, value in candidates.items():

        show_float(
            name,
            value,
            stored,
        )


        if value == stored:

            path_match_counts[
                name
            ] += 1


    per_target[
        target
    ] = {
        "condition_id":
            condition_id,

        "stored":
            stored,

        "stored_hex":
            stored.hex(),

        "candidates": {
            name: {
                "value":
                    value,

                "hex":
                    value.hex(),

                "exact_match":
                    (
                        value == stored
                    ),
            }
            for name, value in candidates.items()
        },
    }


