def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
    text=True,
):

    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=text,
        check=False,
    )

    if check and p.returncode != 0:

        output = (
            p.stdout
            if text
            else
            p.stdout.decode(
                "utf-8",
                errors="replace",
            )
        )

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            output
        )

    return p


def git(
    *args,
    check=True,
):

    return run(
        [
            "git",
            *args,
        ],
        check=check,
        text=True,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def recursively_find(
    obj,
    *,
    path="$",
    predicate,
    result=None,
):

    if result is None:

        result = []


    if isinstance(
        obj,
        dict,
    ):

        for key, value in obj.items():

            child = (
                path
                +
                "."
                +
                str(
                    key
                )
            )


            if predicate(
                str(
                    key
                ),
                value,
            ):

                result.append(
                    {
                        "path":
                            child,

                        "key":
                            str(
                                key
                            ),

                        "value":
                            value,
                    }
                )


            recursively_find(
                value,
                path=child,
                predicate=predicate,
                result=result,
            )


    elif isinstance(
        obj,
        list,
    ):

        for index, value in enumerate(
            obj
        ):

            recursively_find(
                value,
                path=(
                    path
                    +
                    f"[{index}]"
                ),
                predicate=predicate,
                result=result,
            )


    return result


def git_grep(
    pattern,
):

    p = run(
        [
            "git",
            "grep",
            "-n",
            "-I",
            "-e",
            pattern,
            "--",
            "*.py",
            "*.json",
            "*.md",
            "*.txt",
        ],
        check=False,
        text=True,
    )


    if p.returncode not in {
        0,
        1,
    }:

        raise RuntimeError(
            f"git grep failed for {pattern!r}:\n"
            +
            p.stdout
        )


    return [
        line
        for line in p.stdout.splitlines()
        if line.strip()
    ]


def read_context(
    relpath,
    line_number,
    radius=8,
):

    path = (
        REPO
        /
        relpath
    )


    if not path.is_file():

        return None


    try:

        lines = path.read_text(
            encoding="utf-8",
            errors="replace",
        ).splitlines()

    except Exception:

        return None


    start = max(
        1,
        line_number
        -
        radius
    )

    end = min(
        len(
            lines
        ),
        line_number
        +
        radius
    )


    selected = []


    for n in range(
        start,
        end
        +
        1,
    ):

        selected.append(
            f"{n:6d}: {lines[n - 1]}"
        )


    return "\n".join(
        selected
    )


