def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
    text=True,
):

    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=text,
        check=False,
    )

    if check and p.returncode != 0:

        output = (
            p.stdout
            if text
            else
            p.stdout.decode(
                "utf-8",
                errors="replace",
            )
        )

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            output
        )

    return p


def git(
    *args,
    check=True,
):

    return run(
        [
            "git",
            *args,
        ],
        check=check,
        text=True,
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def parse_grep_line(line):

    match = re.match(
        r"^(.*?):(\d+):(.*)$",
        line,
    )

    if not match:

        return None


    return {
        "path":
            match.group(
                1
            ),

        "line":
            int(
                match.group(
                    2
                )
            ),

        "text":
            match.group(
                3
            ),
    }


def read_context(
    relpath,
    line_number,
    radius=12,
):

    path = (
        REPO
        /
        relpath
    )


    if not path.is_file():

        return None


    try:

        lines = path.read_text(
            encoding="utf-8",
            errors="replace",
        ).splitlines()

    except Exception:

        return None


    start = max(
        1,
        line_number
        -
        radius
    )

    end = min(
        len(
            lines
        ),
        line_number
        +
        radius
    )


    return "\n".join(
        f"{n:6d}: {lines[n - 1]}"
        for n in range(
            start,
            end
            +
            1,
        )
    )


def git_show_blob(
    commit,
    relpath,
):

    p = run(
        [
            "git",
            "show",
            f"{commit}:{relpath}",
        ],
        check=False,
        text=True,
    )


    if p.returncode != 0:

        return None


    return p.stdout


def scan_text_for_terms(
    text,
):

    lower = text.lower()


    strong = [
        term
        for term in BOOTSTRAP_STRONG_TERMS
        if term.lower() in lower
    ]


    rng = [
        term
        for term in RNG_TERMS
        if term.lower() in lower
    ]


    summary = [
        term
        for term in SUMMARY_TERMS
        if term.lower() in lower
    ]


    return {
        "bootstrap_terms":
            strong,

        "rng_terms":
            rng,

        "summary_terms":
            summary,
    }


