# 16. HISTORICAL VS CORRECTED P95 CI CHANGE AUDIT
# =============================================================================

banner(
    "STAGE26-6F1 :: HISTORICAL VS CORRECTED P95 CI AUDIT"
)


p95_changes = []


for row in pass_rows:

    old_low, old_high = row[
        "historical_ci95"
    ][
        "p95_batch_latency_ms"
    ]

    new_low, new_high = row[
        "corrected_ci95"
    ][
        "p95_batch_latency_ms"
    ]


    p95_changes.append(
        {
            "condition_id":
                row[
                    "condition_id"
                ],

            "low_abs_change_ms":
                abs(
                    float(
                        new_low
                    )
                    -
                    float(
                        old_low
                    )
                ),

            "high_abs_change_ms":
                abs(
                    float(
                        new_high
                    )
                    -
                    float(
                        old_high
                    )
                ),

            "exact_same_interval":
                (
                    float(
                        new_low
                    )
                    ==
                    float(
                        old_low
                    )
                    and
                    float(
                        new_high
                    )
                    ==
                    float(
                        old_high
                    )
                ),
        }
    )


exact_same_count = sum(
    1
    for row in p95_changes
    if row[
        "exact_same_interval"
    ]
)


max_low_change = max(
    row[
        "low_abs_change_ms"
    ]
    for row in p95_changes
)

max_high_change = max(
    row[
        "high_abs_change_ms"
    ]
    for row in p95_changes
)


print(
    "PASS conditions:",
    len(
        p95_changes
    )
)

print(
    "Historical p95 CI exactly reproduced:",
    exact_same_count
)

print(
    "Historical p95 CI changed:",
    len(
        p95_changes
    )
    -
    exact_same_count
)

print(
    "Maximum |lower-bound change| ms:",
    repr(
        max_low_change
    )
)

print(
    "Maximum |upper-bound change| ms:",
    repr(
        max_high_change
    )
)


