def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
):

    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            p.stdout
        )

    return p


def git(*args):

    return run(
        [
            "git",
            *args,
        ]
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def load_csv(path):

    with Path(path).open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:

        return list(
            csv.DictReader(
                f
            )
        )


def tracked_files_containing(token):

    rows = git(
        "ls-files"
    ).splitlines()

    token_lower = token.lower()

    return [
        row
        for row in rows
        if token_lower in row.lower()
    ]


def text_file(path):

    return Path(
        path
    ).suffix.lower() in {
        ".json",
        ".csv",
        ".txt",
        ".md",
        ".py",
    }


def summarize_json_structure(path):

    try:

        obj = json.loads(
            Path(path).read_text(
                encoding="utf-8"
            )
        )

    except Exception as exc:

        return {
            "parse":
                "FAIL",

            "error":
                repr(
                    exc
                ),
        }


    if isinstance(
        obj,
        dict,
    ):

        return {
            "parse":
                "PASS",

            "type":
                "dict",

            "top_level_keys":
                list(
                    obj.keys()
                ),
        }


    if isinstance(
        obj,
        list,
    ):

        return {
            "parse":
                "PASS",

            "type":
                "list",

            "length":
                len(
                    obj
                ),
        }


    return {
        "parse":
            "PASS",

        "type":
            type(
                obj
            ).__name__,
    }


def scan_json_for_terms(
    obj,
    terms,
    *,
    path="$",
    out=None,
):

    if out is None:
        out = []


    if isinstance(
        obj,
        dict,
    ):

        for key, value in obj.items():

            child = (
                path
                +
                "."
                +
                str(
                    key
                )
            )

            key_lower = str(
                key
            ).lower()


            if any(
                term.lower()
                in
                key_lower
                for term in terms
            ):

                out.append(
                    {
                        "path":
                            child,

                        "value":
                            value,
                    }
                )


            scan_json_for_terms(
                value,
                terms,
                path=child,
                out=out,
            )


    elif isinstance(
        obj,
        list,
    ):

        for index, value in enumerate(
            obj
        ):

            scan_json_for_terms(
                value,
                terms,
                path=(
                    path
                    +
                    f"[{index}]"
                ),
                out=out,
            )


    return out


