def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
):

    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            p.stdout
        )

    return p


def git(*args):

    return run(
        [
            "git",
            *args,
        ]
    ).stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def read_json(path):

    return json.loads(
        Path(path).read_text(
            encoding="utf-8"
        )
    )


def context(
    lines,
    line_number,
    radius=10,
):

    start = max(
        1,
        line_number - radius,
    )

    end = min(
        len(lines),
        line_number + radius,
    )


    return "\n".join(
        f"{n:6d}: {lines[n - 1]}"
        for n in range(
            start,
            end + 1,
        )
    )


def recursive_find_strings(
    obj,
    *,
    path="$",
    result=None,
):

    if result is None:

        result = []


    if isinstance(
        obj,
        dict,
    ):

        for key, value in obj.items():

            child = (
                path
                +
                "."
                +
                str(key)
            )

            recursive_find_strings(
                value,
                path=child,
                result=result,
            )


    elif isinstance(
        obj,
        list,
    ):

        for index, value in enumerate(obj):

            recursive_find_strings(
                value,
                path=f"{path}[{index}]",
                result=result,
            )


    elif isinstance(
        obj,
        str,
    ):

        result.append(
            {
                "path":
                    path,

                "value":
                    obj,
            }
        )


    return result


def repo_file_candidates():

    tracked = git(
        "ls-files"
    ).splitlines()


    result = []


    for relpath in tracked:

        lower = relpath.lower()

        suffix = Path(
            relpath
        ).suffix.lower()


        if suffix != ".py":

            continue


        if (
            "stage26"
            not in lower
            and
            "representation"
            not in lower
            and
            "packet_image"
            not in lower
        ):

            continue


        result.append(
            relpath
        )


    return result


