# =============================================================================
# 1. HELPERS
# =============================================================================

def banner(text):
    print("\n" + "=" * 124)
    print(text)
    print("=" * 124)


def git(*args):
    p = subprocess.run(
        ["git", *args],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(p.stdout)

    return p.stdout.strip()


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        while True:
            block = f.read(8 * 1024 * 1024)

            if not block:
                break

            h.update(block)

    return h.hexdigest()


def read_json(path):
    return json.loads(
        Path(path).read_text(
            encoding="utf-8"
        )
    )


def source_segment(lines, start, end):
    return "\n".join(
        f"{i:6d}: {lines[i - 1]}"
        for i in range(
            max(1, start),
            min(len(lines), end) + 1,
        )
    )


