lines = source_text.splitlines()

tree = ast.parse(
    source_text
)


print(
    "Source lines:",
    len(lines)
)


# =============================================================================
# 5. FIND FUNCTIONS
# =============================================================================

functions = []


for node in ast.walk(tree):

    if isinstance(
        node,
        (
            ast.FunctionDef,
            ast.AsyncFunctionDef,
        ),
    ):

        functions.append(
            {
                "name":
                    node.name,

                "lineno":
                    node.lineno,

                "end_lineno":
                    node.end_lineno,
            }
        )


functions.sort(
    key=lambda x: x[
        "lineno"
    ]
)


print(
    "\nFunctions:"
)

for fn in functions:
    print(
        f"  {fn['lineno']:5d}-{fn['end_lineno']:5d} "
        f"{fn['name']}"
    )


# =============================================================================
# 6. FIND ALL SEMANTICALLY RELEVANT LINES
# =============================================================================

banner(
    "STAGE26-8A1 :: TIMER / LOOP / FINGERPRINT LINES"
)


patterns = {
    "timer":
        re.compile(
            r"perf_counter_ns|perf_counter",
            re.I,
        ),

    "fingerprint":
        re.compile(
            r"fingerprint",
            re.I,
        ),

    "hash":
        re.compile(
            r"sha256|hashlib|digest|hexdigest|tobytes",
            re.I,
        ),

    "timed_runs":
        re.compile(
            r"timed_runs",
            re.I,
        ),

    "warmup_runs":
        re.compile(
            r"warmup_runs",
            re.I,
        ),

    "materialize":
        re.compile(
            r"materialize",
            re.I,
        ),

    "for_loop":
        re.compile(
            r"^\s*for\s+",
        ),
}


hits = {
    key: []
    for key in patterns
}


for number, line in enumerate(
    lines,
    start=1,
):

    for key, pattern in patterns.items():

        if pattern.search(line):
            hits[
                key
            ].append(
                number
            )


for key, values in hits.items():
    print(
        f"{key:16s}:",
        values
    )


# =============================================================================
# 7. AST — LOCATE LOOPS CONTAINING TIMERS
# =============================================================================

banner(
    "STAGE26-8A1 :: REPEATED TIMING LOOP STRUCTURE"
)


timing_loops = []


for node in ast.walk(tree):

    if not isinstance(
        node,
        (
            ast.For,
            ast.While,
        ),
    ):
        continue


    start = node.lineno
    end = node.end_lineno


    timer_lines = [
        n
        for n in hits[
            "timer"
        ]
        if start <= n <= end
    ]

    fp_lines = sorted(
        set(
            [
                n
                for n in hits[
                    "fingerprint"
                ]
                if start <= n <= end
            ]
            +
            [
                n
                for n in hits[
                    "hash"
                ]
                if start <= n <= end
            ]
        )
    )


    if timer_lines:

        try:
            loop_header = ast.unparse(
                node
            ).splitlines()[0]

        except Exception:
            loop_header = lines[
                start - 1
            ].strip()


        timing_loops.append(
            {
                "start":
                    start,

                "end":
                    end,

                "header":
                    loop_header,

                "timer_lines":
                    timer_lines,

                "fingerprint_hash_lines":
                    fp_lines,
            }
        )


for index, item in enumerate(
    timing_loops,
    start=1,
):

    print(
        f"\nTIMING LOOP {index}"
    )

    print(
        "  lines       :",
        item[
            "start"
        ],
        "-",
        item[
            "end"
        ]
    )

    print(
        "  timer lines :",
        item[
            "timer_lines"
        ]
    )

    print(
        "  hash/fp     :",
        item[
            "fingerprint_hash_lines"
        ]
    )

    print(
        "\n"
        +
        source_segment(
            lines,
            item[
                "start"
            ],
            item[
                "end"
            ],
        )
    )


# =============================================================================
# 8. AST CALL ORDER WITHIN TIMING LOOPS
# =============================================================================

banner(
    "STAGE26-8A1 :: CALL ORDER WITHIN TIMING LOOPS"
)


call_records = []


for loop_index, loop_info in enumerate(
    timing_loops,
    start=1,
):

    start = loop_info[
        "start"
    ]

    end = loop_info[
        "end"
    ]


    loop_node = None


    for node in ast.walk(tree):

        if (
            isinstance(
                node,
                (
                    ast.For,
                    ast.While,
                ),
            )
            and
            node.lineno == start
            and
            node.end_lineno == end
        ):
            loop_node = node
            break


    if loop_node is None:
        raise RuntimeError(
            "Could not recover timing-loop AST node."
        )


    local_calls = []


    for subnode in ast.walk(
        loop_node
    ):

        if not isinstance(
            subnode,
            ast.Call,
        ):
            continue


        try:
            call_name = ast.unparse(
                subnode.func
            )

        except Exception:
            call_name = "<unparse-failed>"


        local_calls.append(
            {
                "line":
                    subnode.lineno,

                "call":
                    call_name,
            }
        )


    local_calls.sort(
        key=lambda x: (
            x[
                "line"
            ],
            x[
                "call"
            ],
        )
    )


    print(
        f"\nTIMING LOOP {loop_index} CALLS:"
    )


    for record in local_calls:
        print(
            f"  {record['line']:5d}: "
            f"{record['call']}"
        )


    call_records.append(
        {
            "loop_index":
                loop_index,

            "loop_start":
                start,

            "loop_end":
                end,

            "calls":
                local_calls,
        }
    )


# =============================================================================
# 9. EXACT TIMER / FINGERPRINT ORDER CLASSIFICATION
# =============================================================================

banner(
    "STAGE26-8A1 :: EXACT ORDER CLASSIFICATION"
)


classification_evidence = []

classification = (
    "NOT_RESOLVABLE_FROM_EXACT_WORKER"
)


for loop in timing_loops:

    timer_lines = sorted(
        loop[
            "timer_lines"
        ]
    )


    if len(timer_lines) < 2:
        continue


    timer_start = timer_lines[
        0
    ]

    timer_stop = timer_lines[
        1
    ]


    fp_hash_lines = sorted(
        loop[
            "fingerprint_hash_lines"
        ]
    )


    inside_timer = [
        line
        for line in fp_hash_lines
        if timer_start
        <
        line
        <
        timer_stop
    ]


    after_timer_before_loop_end = [
        line
        for line in fp_hash_lines
        if timer_stop
        <
        line
        <=
        loop[
            "end"
        ]
    ]


    evidence = {
        "loop_start":
            loop[
                "start"
            ],

        "loop_end":
            loop[
                "end"
            ],

        "timer_start_line":
            timer_start,

        "timer_stop_line":
            timer_stop,

        "fingerprint_hash_inside_timer":
            inside_timer,

        "fingerprint_hash_after_timer_before_next_iteration":
            after_timer_before_loop_end,
    }


    classification_evidence.append(
        evidence
    )


    print(
        json.dumps(
            evidence,
            indent=2,
            sort_keys=True,
        )
    )


    if after_timer_before_loop_end:

        classification = (
            "OUTSIDE_TIMER_BEFORE_NEXT_TIMED_ITERATION"
        )

        break


    if inside_timer:

        classification = (
            "INSIDE_TIMER"
        )

        break


# If there is no fingerprint/hash inside a repeated timed loop,
# inspect whether hashing occurs only after the timing loops finish.

if classification == (
    "NOT_RESOLVABLE_FROM_EXACT_WORKER"
):

    if timing_loops:

        last_timing_loop_end = max(
            item[
                "end"
            ]
            for item in timing_loops
        )


        all_fp_hash = sorted(
            set(
                hits[
                    "fingerprint"
                ]
                +
                hits[
                    "hash"
                ]
            )
        )


        relevant_after = [
            n
            for n in all_fp_hash
            if n > last_timing_loop_end
        ]


        relevant_before_or_inside = [
            n
            for n in all_fp_hash
            if n <= last_timing_loop_end
        ]


        if (
            relevant_after
            and
            not relevant_before_or_inside
        ):

            classification = (
                "OUTSIDE_TIMER_AFTER_ALL_TIMED_ITERATIONS"
            )


print(
    "\nFINAL EXACT-WORKER CLASSIFICATION:"
)

print(
    " ",
    classification
)


