# =============================================================================
# 1. HELPERS
# =============================================================================

def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(
    path,
    *,
    progress=False,
):

    path = Path(path)

    h = hashlib.sha256()

    total = 0

    next_report = (
        512 * 1024 * 1024
    )


    with path.open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

            total += len(
                block
            )


            if (
                progress
                and
                total >= next_report
            ):

                print(
                    f"      hashed {total / (1024**3):.2f} GiB"
                )

                next_report += (
                    512 * 1024 * 1024
                )


    return h.hexdigest()


