def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
):

    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            "$ "
            +
            " ".join(
                map(
                    str,
                    cmd,
                )
            )
            +
            "\n\n"
            +
            p.stdout
        )

    return p


def git(*args):

    return run(
        [
            "git",
            *args,
        ]
    ).stdout.strip()


def sha256_file(
    path,
    *,
    progress=False,
):

    path = Path(
        path
    )

    h = hashlib.sha256()

    total = 0

    next_report = (
        512 * 1024 * 1024
    )


    with path.open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

            total += len(
                block
            )


            if (
                progress
                and
                total >= next_report
            ):

                print(
                    f"  hashed {total / (1024**3):.2f} GiB"
                )

                next_report += (
                    512 * 1024 * 1024
                )


    return h.hexdigest()


def atomic_json(
    path,
    payload,
):

    path = Path(
        path
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    tmp = Path(
        str(
            path
        )
        +
        ".tmp"
    )


    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            payload,
            f,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )


    os.replace(
        tmp,
        path,
    )


