def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def atomic_json(path, payload):

    path = Path(
        path
    )

    tmp = Path(
        str(path)
        +
        ".tmp"
    )


    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            payload,
            f,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )


    os.replace(
        tmp,
        path,
    )


def write_csv(
    path,
    rows,
    fieldnames,
):

    with Path(path).open(
        "w",
        encoding="utf-8",
        newline="",
    ) as f:

        writer = csv.DictWriter(
            f,
            fieldnames=fieldnames,
        )

        writer.writeheader()

        writer.writerows(
            rows
        )


def finite_positive(
    value,
    label,
):

    x = float(
        value
    )

    if (
        not math.isfinite(
            x
        )
        or
        x <= 0
    ):

        raise RuntimeError(
            f"{label}: expected finite positive value; got {value!r}"
        )

    return x


