# 10. ENVIRONMENT GATE
# =============================================================================

def environment_gate():

    attempts = []


    for attempt in range(
        1,
        ENVIRONMENT_GATE_ATTEMPTS + 1,
    ):

        cpu_percent = float(
            psutil.cpu_percent(
                interval=1.0
            )
        )

        available_ram_bytes = int(
            psutil.virtual_memory().available
        )

        available_ram_gib = (
            available_ram_bytes
            /
            1024**3
        )


        passed = (
            cpu_percent
            <=
            MAX_CPU_PERCENT
            and
            available_ram_gib
            >=
            MIN_AVAILABLE_RAM_GIB
        )


        attempts.append(
            {
                "attempt":
                    attempt,

                "cpu_percent":
                    cpu_percent,

                "available_ram_bytes":
                    available_ram_bytes,

                "available_ram_gib":
                    available_ram_gib,

                "passed":
                    passed,
            }
        )


        print(
            f"    gate attempt {attempt}: "
            f"CPU={cpu_percent:.1f}% "
            f"RAM={available_ram_gib:.3f} GiB "
            f"{'PASS' if passed else 'FAIL'}"
        )


        if passed:

            return (
                True,
                attempts,
            )


        if attempt < ENVIRONMENT_GATE_ATTEMPTS:

            time.sleep(
                ENVIRONMENT_GATE_RETRY_SECONDS
            )


    return (
        False,
        attempts,
    )


# =============================================================================
# 11. RESULT SUMMARIZER
# =============================================================================

def summarize_worker_result(
    result,
    *,
    batch,
    expected_timed_runs,
):

    if result.get(
        "status"
    ) != "PASS":

        raise RuntimeError(
            f"Worker result status is not PASS: {result.get('status')!r}"
        )


    observations = result.get(
        "observations"
    )


    if not isinstance(
        observations,
        list,
    ):

        raise RuntimeError(
            "Worker result observations missing."
        )


    if len(
        observations
    ) != expected_timed_runs:

        raise RuntimeError(
            f"Observation count mismatch: "
            f"{len(observations)} != {expected_timed_runs}"
        )


    elapsed_ns = np.asarray(
        [
            int(
                row[
                    "elapsed_ns"
                ]
            )
            for row in observations
        ],
        dtype=np.int64,
    )


    if np.any(
        elapsed_ns
        <=
        0
    ):

        raise RuntimeError(
            "Non-positive elapsed_ns observation."
        )


    flows = np.asarray(
        [
            int(
                row[
                    "flows"
                ]
            )
            for row in observations
        ],
        dtype=np.int64,
    )


    if not np.all(
        flows
        ==
        batch
    ):

        raise RuntimeError(
            "Worker observation flow count differs from frozen batch."
        )


    throughput = np.asarray(
        [
            float(
                row[
                    "flows_per_second"
                ]
            )
            for row in observations
        ],
        dtype=np.float64,
    )


    if (
        np.any(
            ~np.isfinite(
                throughput
            )
        )
        or
        np.any(
            throughput
            <=
            0
        )
    ):

        raise RuntimeError(
            "Invalid flows_per_second observation."
        )


    # Frozen latency conversion policy:
    # float64 elapsed_ns -> ms before percentile.
    elapsed_ms = (
        elapsed_ns.astype(
            np.float64
        )
        /
        1_000_000.0
    )


    summary = {
        "n":
            int(
                len(
                    elapsed_ns
                )
            ),

        "p50_latency_ms":
            float(
                np.percentile(
                    elapsed_ms,
                    50,
                    method="linear",
                )
            ),

        "p95_latency_ms":
            float(
                np.percentile(
                    elapsed_ms,
                    95,
                    method="linear",
                )
            ),

        "p99_latency_ms":
            (
                float(
                    np.percentile(
                        elapsed_ms,
                        99,
                        method="linear",
                    )
                )
                if
                len(
                    elapsed_ns
                )
                >=
                100
                else
                None
            ),

        "median_throughput_flows_per_second":
            float(
                np.median(
                    throughput
                )
            ),

        "min_throughput_flows_per_second":
            float(
                np.min(
                    throughput
                )
            ),

        "max_throughput_flows_per_second":
            float(
                np.max(
                    throughput
                )
            ),

        "representation_fingerprint_sha256":
            result.get(
                "representation_fingerprint_sha256"
            ),

        "warm_representation_fingerprint_sha256":
            result.get(
                "warm_representation_fingerprint_sha256"
            ),
    }


    for key in [
        "p50_latency_ms",
        "p95_latency_ms",
        "median_throughput_flows_per_second",
    ]:

        finite_positive(
            summary[
                key
            ],
            key,
        )


    if summary[
        "p99_latency_ms"
    ] is not None:

        finite_positive(
            summary[
                "p99_latency_ms"
            ],
            "p99_latency_ms",
        )


    return (
        summary,
        observations,
    )


