worker_execution_rows = []

raw_observation_rows = []

worker_outputs = {}

worker_execution_counter = 0


def execute_worker(
    *,
    block,
    variant,
):

    global worker_execution_counter

    worker_execution_counter += 1


    block_index = int(
        block[
            "pair_block_execution_index"
        ]
    )

    batch = int(
        block[
            "batch_size"
        ]
    )

    pair_rep = int(
        block[
            "pair_rep"
        ]
    )


    if variant == "V2_ORIGINAL":

        worker_path = V2_WORKER

        worker_sha = EXPECTED_V2_SHA256

        invocation = v2_invocation

    elif variant == "V3_CLEAN":

        worker_path = V3_WORKER

        worker_sha = EXPECTED_V3_SHA256

        invocation = v3_invocation

    else:

        raise RuntimeError(
            f"Unknown frozen variant: {variant}"
        )


    historical = historical_configs[
        batch
    ]

    cfg = copy.deepcopy(
        historical[
            "config"
        ]
    )


    stem = (
        f"block_{block_index:02d}"
        f"__B{batch}"
        f"__pair_{pair_rep}"
        f"__{variant.lower()}"
    )


    config_path = (
        CONFIG_DIR
        /
        (
            stem
            +
            "_config.json"
        )
    )

    result_path = (
        RESULT_DIR
        /
        (
            stem
            +
            "_result.json"
        )
    )

    log_path = (
        LOG_DIR
        /
        (
            stem
            +
            ".log"
        )
    )


    # Only execution-specific fields change.
    # Historical timing/sample semantics remain exactly inherited.
    cfg[
        "result_path"
    ] = str(
        result_path
    )

    cfg[
        "worker_sha256"
    ] = worker_sha


    atomic_json(
        config_path,
        cfg,
    )


    config_sha = sha256_file(
        config_path
    )


    print(
        f"\n  WORKER {worker_execution_counter:02d}/50 "
        f"{variant}"
    )

    print(
        "    config SHA:",
        config_sha
    )


    gate_passed, gate_attempts = environment_gate()


    execution_row = {
        "worker_execution_index":
            worker_execution_counter,

        "pair_block_execution_index":
            block_index,

        "batch_size":
            batch,

        "pair_rep":
            pair_rep,

        "variant":
            variant,

        "worker_sha256":
            worker_sha,

        "historical_config_sha256":
            historical[
                "sha256"
            ],

        "execution_config_sha256":
            config_sha,

        "environment_gate_passed":
            gate_passed,

        "worker_status":
            None,

        "worker_return_code":
            None,

        "failure_class":
            None,

        "result_sha256":
            None,

        "n":
            None,

        "p50_latency_ms":
            None,

        "p95_latency_ms":
            None,

        "p99_latency_ms":
            None,

        "median_throughput_flows_per_second":
            None,

        "representation_fingerprint_sha256":
            None,
    }


    if not gate_passed:

        execution_row[
            "worker_status"
        ] = "ENVIRONMENT_GATE_FAILED"

        execution_row[
            "failure_class"
        ] = "ENVIRONMENT_GATE_RESOURCE_STATE"

        worker_execution_rows.append(
            execution_row
        )


        return {
            "status":
                "ENVIRONMENT_GATE_FAILED",

            "summary":
                None,

            "result":
                None,

            "gate_attempts":
                gate_attempts,

            "config_path":
                str(
                    config_path
                ),

            "log_path":
                None,
        }


    cmd = invocation[
        "build"
    ](
        config_path
    )


    print(
        "    fresh process: YES"
    )

    print(
        "    CPU affinity : [0]"
    )


    started_utc = datetime.now(
        timezone.utc
    ).isoformat()


    try:

        p = subprocess.run(
            cmd,
            cwd=REPO,
            env=worker_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            timeout=WORKER_TIMEOUT_SECONDS,
            check=False,
        )


        return_code = int(
            p.returncode
        )

        output_text = (
            p.stdout
            or
            ""
        )


        log_path.write_text(
            output_text,
            encoding="utf-8",
        )


        execution_row[
            "worker_return_code"
        ] = return_code


        print(
            "    return code  :",
            return_code
        )


        if return_code != 0:

            execution_row[
                "worker_status"
            ] = "WORKER_FAILED"

            execution_row[
                "failure_class"
            ] = "NONZERO_RETURN_CODE"

            worker_execution_rows.append(
                execution_row
            )


            print(
                "    status       : WORKER_FAILED"
            )


            if output_text.strip():

                print(
                    "    log tail:"
                )


                for line in output_text.splitlines()[
                    -20:
                ]:

                    print(
                        "      ",
                        line
                    )


            return {
                "status":
                    "WORKER_FAILED",

                "summary":
                    None,

                "result":
                    None,

                "gate_attempts":
                    gate_attempts,

                "config_path":
                    str(
                        config_path
                    ),

                "log_path":
                    str(
                        log_path
                    ),
            }


    except subprocess.TimeoutExpired as exc:

        output_text = (
            exc.stdout
            or
            ""
        )


        if isinstance(
            output_text,
            bytes,
        ):

            output_text = output_text.decode(
                "utf-8",
                errors="replace",
            )


        log_path.write_text(
            output_text,
            encoding="utf-8",
        )


        execution_row[
            "worker_status"
        ] = "TIMEOUT_RESOURCE_LIMIT"

        execution_row[
            "failure_class"
        ] = "TIMEOUT_RESOURCE_LIMIT"

        worker_execution_rows.append(
            execution_row
        )


        print(
            "    status       : TIMEOUT_RESOURCE_LIMIT"
        )


        return {
            "status":
                "TIMEOUT_RESOURCE_LIMIT",

            "summary":
                None,

            "result":
                None,

            "gate_attempts":
                gate_attempts,

            "config_path":
                str(
                    config_path
                ),

            "log_path":
                str(
                    log_path
                ),
        }


    finished_utc = datetime.now(
        timezone.utc
    ).isoformat()


    if not result_path.is_file():

        execution_row[
            "worker_status"
        ] = "RESULT_FILE_MISSING"

        execution_row[
            "failure_class"
        ] = "WORKER_OUTPUT_CONTRACT_FAILURE"

        worker_execution_rows.append(
            execution_row
        )


        print(
            "    status       : RESULT_FILE_MISSING"
        )


        return {
            "status":
                "RESULT_FILE_MISSING",

            "summary":
                None,

            "result":
                None,

            "gate_attempts":
                gate_attempts,

            "config_path":
                str(
                    config_path
                ),

            "log_path":
                str(
                    log_path
                ),
        }


    result_sha = sha256_file(
        result_path
    )


    result = json.loads(
        result_path.read_text(
            encoding="utf-8"
        )
    )


    try:

        summary, observations = summarize_worker_result(
            result,
            batch=batch,
            expected_timed_runs=int(
                cfg[
                    "timed_runs"
                ]
            ),
        )


    except Exception as exc:

        execution_row[
            "worker_status"
        ] = "RESULT_VALIDATION_FAILED"

        execution_row[
            "failure_class"
        ] = (
            type(
                exc
            ).__name__
            +
            ": "
            +
            str(
                exc
            )
        )

        execution_row[
            "result_sha256"
        ] = result_sha

        worker_execution_rows.append(
            execution_row
        )


        print(
            "    status       : RESULT_VALIDATION_FAILED"
        )

        print(
            "    reason       :",
            repr(
                exc
            )
        )


        return {
            "status":
                "RESULT_VALIDATION_FAILED",

            "summary":
                None,

            "result":
                result,

            "gate_attempts":
                gate_attempts,

            "config_path":
                str(
                    config_path
                ),

            "result_path":
                str(
                    result_path
                ),

            "log_path":
                str(
                    log_path
                ),
        }


    execution_row.update(
        {
            "worker_status":
                "PASS",

            "result_sha256":
                result_sha,

            "n":
                summary[
                    "n"
                ],

            "p50_latency_ms":
                summary[
                    "p50_latency_ms"
                ],

            "p95_latency_ms":
                summary[
                    "p95_latency_ms"
                ],

            "p99_latency_ms":
                summary[
                    "p99_latency_ms"
                ],

            "median_throughput_flows_per_second":
                summary[
                    "median_throughput_flows_per_second"
                ],

            "representation_fingerprint_sha256":
                summary[
                    "representation_fingerprint_sha256"
                ],
        }
    )


    worker_execution_rows.append(
        execution_row
    )


    for observation in observations:

        raw_observation_rows.append(
            {
                "worker_execution_index":
                    worker_execution_counter,

                "pair_block_execution_index":
                    block_index,

                "batch_size":
                    batch,

                "pair_rep":
                    pair_rep,

                "variant":
                    variant,

                "iteration_index":
                    int(
                        observation[
                            "iteration_index"
                        ]
                    ),

                "elapsed_ns":
                    int(
                        observation[
                            "elapsed_ns"
                        ]
                    ),

                "elapsed_seconds":
                    float(
                        observation[
                            "elapsed_seconds"
                        ]
                    ),

                "flows":
                    int(
                        observation[
                            "flows"
                        ]
                    ),

                "flows_per_second":
                    float(
                        observation[
                            "flows_per_second"
                        ]
                    ),
            }
        )


    print(
        "    status       : PASS"
    )

    print(
        f"    p50          : "
        f"{summary['p50_latency_ms']:.6f} ms"
    )

    print(
        f"    p95          : "
        f"{summary['p95_latency_ms']:.6f} ms"
    )


    if summary[
        "p99_latency_ms"
    ] is None:

        print(
            "    p99          : N/A"
        )

    else:

        print(
            f"    p99          : "
            f"{summary['p99_latency_ms']:.6f} ms"
        )


    print(
        f"    median flows/s: "
        f"{summary['median_throughput_flows_per_second']:,.3f}"
    )

    print(
        "    fingerprint  :",
        summary[
            "representation_fingerprint_sha256"
        ]
    )


    return {
        "status":
            "PASS",

        "summary":
            summary,

        "result":
            result,

        "gate_attempts":
            gate_attempts,

        "started_utc":
            started_utc,

        "finished_utc":
            finished_utc,

        "config_path":
            str(
                config_path
            ),

        "result_path":
            str(
                result_path
            ),

        "log_path":
            str(
                log_path
            ),

        "result_sha256":
            result_sha,
    }


# =============================================================================
# 13. EXECUTE EXACT FROZEN PAIR ORDER
# =============================================================================

banner(
    "STAGE26-8C1 :: EXECUTE 25 FROZEN PAIR BLOCKS"
)


pair_result_rows = []


for block in pair_blocks:

    block_index = int(
        block[
            "pair_block_execution_index"
        ]
    )

    batch = int(
        block[
            "batch_size"
        ]
    )

    pair_rep = int(
        block[
            "pair_rep"
        ]
    )

    order = list(
        block[
            "within_pair_order"
        ]
    )


    print(
        "\n"
        +
        "-" * 124
    )

    print(
        f"PAIR BLOCK {block_index:02d}/25 "
        f":: B={batch} "
        f":: pair={pair_rep} "
        f":: order={order}"
    )

    print(
        "-" * 124
    )


    outputs = {}


    # Frozen within-pair order.
    for variant in order:

        outputs[
            variant
        ] = execute_worker(
            block=block,
            variant=variant,
        )


    worker_outputs[
        (
            batch,
            pair_rep,
        )
    ] = outputs


    v2 = outputs[
        "V2_ORIGINAL"
    ]

    v3 = outputs[
        "V3_CLEAN"
    ]


    complete = (
        v2[
            "status"
        ]
        ==
        "PASS"
        and
        v3[
            "status"
        ]
        ==
        "PASS"
    )


    pair_row = {
        "pair_block_execution_index":
            block_index,

        "batch_size":
            batch,

        "pair_rep":
            pair_rep,

        "within_pair_order":
            " -> ".join(
                order
            ),

        "V2_status":
            v2[
                "status"
            ],

        "V3_status":
            v3[
                "status"
            ],

        "pair_complete":
            complete,

        "V2_median_throughput_flows_per_second":
            None,

        "V3_median_throughput_flows_per_second":
            None,

        "throughput_ratio_clean_over_original":
            None,

        "V2_p50_latency_ms":
            None,

        "V3_p50_latency_ms":
            None,

        "p50_latency_ratio_clean_over_original":
            None,

        "V2_p95_latency_ms":
            None,

        "V3_p95_latency_ms":
            None,

        "p95_latency_ratio_clean_over_original":
            None,

        "V2_p99_latency_ms":
            None,

        "V3_p99_latency_ms":
            None,

        "p99_latency_ratio_clean_over_original":
            None,

        "V2_fingerprint":
            None,

        "V3_fingerprint":
            None,

        "fingerprint_equal":
            None,
    }


    if complete:

        s2 = v2[
            "summary"
        ]

        s3 = v3[
            "summary"
        ]


        fingerprint_equal = (
            s2[
                "representation_fingerprint_sha256"
            ]
            ==
            s3[
                "representation_fingerprint_sha256"
            ]
        )


        if not fingerprint_equal:

            raise RuntimeError(
                f"B={batch}/pair={pair_rep}: "
                "V2/V3 representation fingerprints differ."
            )


        throughput_ratio = (
            s3[
                "median_throughput_flows_per_second"
            ]
            /
            s2[
                "median_throughput_flows_per_second"
            ]
        )


        p50_ratio = (
            s3[
                "p50_latency_ms"
            ]
            /
            s2[
                "p50_latency_ms"
            ]
        )


        p95_ratio = (
            s3[
                "p95_latency_ms"
            ]
            /
            s2[
                "p95_latency_ms"
            ]
        )


        if (
            s2[
                "p99_latency_ms"
            ]
            is not None
            and
            s3[
                "p99_latency_ms"
            ]
            is not None
        ):

            p99_ratio = (
                s3[
                    "p99_latency_ms"
                ]
                /
                s2[
                    "p99_latency_ms"
                ]
            )

        else:

            p99_ratio = None


        pair_row.update(
            {
                "V2_median_throughput_flows_per_second":
                    s2[
                        "median_throughput_flows_per_second"
                    ],

                "V3_median_throughput_flows_per_second":
                    s3[
                        "median_throughput_flows_per_second"
                    ],

                "throughput_ratio_clean_over_original":
                    throughput_ratio,

                "V2_p50_latency_ms":
                    s2[
                        "p50_latency_ms"
                    ],

                "V3_p50_latency_ms":
                    s3[
                        "p50_latency_ms"
                    ],

                "p50_latency_ratio_clean_over_original":
                    p50_ratio,

                "V2_p95_latency_ms":
                    s2[
                        "p95_latency_ms"
                    ],

                "V3_p95_latency_ms":
                    s3[
                        "p95_latency_ms"
                    ],

                "p95_latency_ratio_clean_over_original":
                    p95_ratio,

                "V2_p99_latency_ms":
                    s2[
                        "p99_latency_ms"
                    ],

                "V3_p99_latency_ms":
                    s3[
                        "p99_latency_ms"
                    ],

                "p99_latency_ratio_clean_over_original":
                    p99_ratio,

                "V2_fingerprint":
                    s2[
                        "representation_fingerprint_sha256"
                    ],

                "V3_fingerprint":
                    s3[
                        "representation_fingerprint_sha256"
                    ],

                "fingerprint_equal":
                    fingerprint_equal,
            }
        )


        print(
            "\n  PAIR RESULT: COMPLETE"
        )

        print(
            f"    throughput V3/V2 : "
            f"{throughput_ratio:.9f}"
        )

        print(
            f"    p50 V3/V2        : "
            f"{p50_ratio:.9f}"
        )

        print(
            f"    p95 V3/V2        : "
            f"{p95_ratio:.9f}"
        )


        if p99_ratio is not None:

            print(
                f"    p99 V3/V2        : "
                f"{p99_ratio:.9f}"
            )

        else:

            print(
                "    p99 V3/V2        : N/A"
            )


        print(
            "    fingerprint equal:",
            fingerprint_equal
        )


    else:

        print(
            "\n  PAIR RESULT: INCOMPLETE — NO REPLACEMENT"
        )

        print(
            "    V2:",
            v2[
                "status"
            ]
        )

        print(
            "    V3:",
            v3[
                "status"
            ]
        )


    pair_result_rows.append(
        pair_row
    )


