# 15. BATCH-LEVEL FROZEN DESCRIPTIVE SUMMARIES
# =============================================================================

banner(
    "STAGE26-8C1 :: BATCH-LEVEL PAIRED SENSITIVITY SUMMARY"
)


batch_summary_rows = []


for batch in BATCHES:

    rows = [
        row
        for row in complete_pairs
        if int(
            row[
                "batch_size"
            ]
        )
        ==
        batch
    ]


    throughput_ratios = [
        float(
            row[
                "throughput_ratio_clean_over_original"
            ]
        )
        for row in rows
    ]

    p50_ratios = [
        float(
            row[
                "p50_latency_ratio_clean_over_original"
            ]
        )
        for row in rows
    ]

    p95_ratios = [
        float(
            row[
                "p95_latency_ratio_clean_over_original"
            ]
        )
        for row in rows
    ]

    p99_ratios = [
        float(
            row[
                "p99_latency_ratio_clean_over_original"
            ]
        )
        for row in rows
        if row[
            "p99_latency_ratio_clean_over_original"
        ]
        is not None
    ]


    def descriptor(
        values
    ):

        if not values:

            return {
                "median":
                    None,

                "min":
                    None,

                "max":
                    None,
            }


        arr = np.asarray(
            values,
            dtype=np.float64,
        )


        return {
            "median":
                float(
                    np.median(
                        arr
                    )
                ),

            "min":
                float(
                    np.min(
                        arr
                    )
                ),

            "max":
                float(
                    np.max(
                        arr
                    )
                ),
        }


    throughput_desc = descriptor(
        throughput_ratios
    )

    p50_desc = descriptor(
        p50_ratios
    )

    p95_desc = descriptor(
        p95_ratios
    )

    p99_desc = descriptor(
        p99_ratios
    )


    row = {
        "batch_size":
            batch,

        "frozen_pair_count":
            5,

        "complete_pair_count":
            len(
                rows
            ),

        "incomplete_pair_count":
            5
            -
            len(
                rows
            ),

        "throughput_ratio_pair_values":
            json.dumps(
                throughput_ratios
            ),

        "throughput_ratio_median":
            throughput_desc[
                "median"
            ],

        "throughput_ratio_min":
            throughput_desc[
                "min"
            ],

        "throughput_ratio_max":
            throughput_desc[
                "max"
            ],

        "p50_ratio_pair_values":
            json.dumps(
                p50_ratios
            ),

        "p50_ratio_median":
            p50_desc[
                "median"
            ],

        "p50_ratio_min":
            p50_desc[
                "min"
            ],

        "p50_ratio_max":
            p50_desc[
                "max"
            ],

        "p95_ratio_pair_values":
            json.dumps(
                p95_ratios
            ),

        "p95_ratio_median":
            p95_desc[
                "median"
            ],

        "p95_ratio_min":
            p95_desc[
                "min"
            ],

        "p95_ratio_max":
            p95_desc[
                "max"
            ],

        "p99_ratio_pair_values":
            (
                json.dumps(
                    p99_ratios
                )
                if p99_ratios
                else
                ""
            ),

        "p99_ratio_median":
            p99_desc[
                "median"
            ],

        "p99_ratio_min":
            p99_desc[
                "min"
            ],

        "p99_ratio_max":
            p99_desc[
                "max"
            ],

        "bootstrap":
            False,

        "hypothesis_test":
            False,

        "materiality_threshold":
            "",
    }


    batch_summary_rows.append(
        row
    )


    print(
        f"\nB={batch}"
    )

    print(
        f"  complete pairs : "
        f"{len(rows)}/5"
    )


    if throughput_ratios:

        print(
            "  throughput V3/V2 pair ratios:"
        )

        print(
            "   ",
            [
                round(
                    x,
                    9,
                )
                for x in throughput_ratios
            ]
        )

        print(
            f"  throughput median/min/max : "
            f"{throughput_desc['median']:.9f} / "
            f"{throughput_desc['min']:.9f} / "
            f"{throughput_desc['max']:.9f}"
        )

        print(
            f"  p50 median V3/V2          : "
            f"{p50_desc['median']:.9f}"
        )

        print(
            f"  p95 median V3/V2          : "
            f"{p95_desc['median']:.9f}"
        )


        if p99_desc[
            "median"
        ] is not None:

            print(
                f"  p99 median V3/V2          : "
                f"{p99_desc['median']:.9f}"
            )

        else:

            print(
                "  p99 median V3/V2          : N/A"
            )


    else:

        print(
            "  no complete frozen pair available"
        )


