def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def git(*args):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def atomic_json(path, payload):

    path = Path(
        path
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    tmp = Path(
        str(path)
        +
        ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            payload,
            f,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def flatten_json(
    obj,
    *,
    prefix="$",
    result=None,
):

    if result is None:

        result = []


    if isinstance(
        obj,
        dict,
    ):

        for key, value in obj.items():

            flatten_json(
                value,
                prefix=(
                    prefix
                    +
                    "."
                    +
                    str(
                        key
                    )
                ),
                result=result,
            )


    elif isinstance(
        obj,
        list,
    ):

        for index, value in enumerate(
            obj
        ):

            flatten_json(
                value,
                prefix=(
                    f"{prefix}[{index}]"
                ),
                result=result,
            )


    else:

        result.append(
            {
                "path":
                    prefix,

                "value":
                    obj,
            }
        )


    return result


def safe_json(path):

    try:

        return json.loads(
            Path(path).read_text(
                encoding="utf-8"
            )
        )

    except Exception:

        return None


def file_inventory(
    root,
    *,
    max_hash_size=20 * 1024 * 1024,
):

    rows = []


    if not Path(root).exists():

        return rows


    for path in sorted(
        p
        for p in Path(root).rglob(
            "*"
        )
        if p.is_file()
    ):

        size = int(
            path.stat().st_size
        )


        row = {
            "repo_relative_path":
                str(
                    path.relative_to(
                        REPO
                    )
                ),

            "size_bytes":
                size,

            "suffix":
                path.suffix.lower(),

            "sha256":
                (
                    sha256_file(
                        path
                    )
                    if size
                    <=
                    max_hash_size
                    else
                    None
                ),
        }


        rows.append(
            row
        )


    return rows


