# =============================================================================
# 1. HELPERS
# =============================================================================

def banner(text):

    print(
        "\n"
        + "=" * 124
    )

    print(text)

    print(
        "=" * 124
    )


def git(
    *args,
    check=True,
):

    p = subprocess.run(
        [
            "git",
            *args,
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return p.stdout.strip()


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8 * 1024 * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def atomic_json(
    path,
    payload,
):

    path = Path(
        path
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    tmp = Path(
        str(path)
        +
        ".tmp"
    )


    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            payload,
            f,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )


    os.replace(
        tmp,
        path,
    )


def safe_json(path):

    try:

        return json.loads(
            Path(path).read_text(
                encoding="utf-8"
            )
        )

    except Exception:

        return None


def flatten_json(
    value,
    prefix="$",
    output=None,
):

    if output is None:

        output = []


    if isinstance(
        value,
        dict,
    ):

        for key, child in value.items():

            flatten_json(
                child,
                (
                    prefix
                    +
                    "."
                    +
                    str(
                        key
                    )
                ),
                output,
            )


    elif isinstance(
        value,
        list,
    ):

        for index, child in enumerate(
            value
        ):

            flatten_json(
                child,
                f"{prefix}[{index}]",
                output,
            )


    else:

        output.append(
            {
                "path":
                    prefix,

                "value":
                    value,
            }
        )


    return output


def source_context(
    lines,
    line_number,
    radius=5,
):

    start = max(
        1,
        line_number
        -
        radius,
    )

    end = min(
        len(
            lines
        ),
        line_number
        +
        radius,
    )


    return "\n".join(
        f"{i:6d}: {lines[i - 1]}"
        for i in range(
            start,
            end + 1,
        )
    )


