def banner(text):

    print(
        "\n"
        + "=" * 120
    )

    print(
        text
    )

    print(
        "=" * 120
    )


def run(
    cmd,
    *,
    cwd=REPO,
    check=True,
    env=None,
):

    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
        env=env,
    )

    if (
        check
        and
        p.returncode != 0
    ):

        raise RuntimeError(
            f"Command failed ({p.returncode}): "
            f"{' '.join(map(str, cmd))}\n"
            f"{p.stdout}"
        )

    return p.stdout.strip()


def git(
    *args,
    check=True,
    env=None,
):

    return run(
        [
            "git",
            *args,
        ],
        check=check,
        env=env,
    )


def sha256_file(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                8
                * 1024
                * 1024
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def sha256_bytes(data):

    return hashlib.sha256(
        data
    ).hexdigest()


def atomic_json(
    path,
    payload,
):

    path = Path(
        path
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    tmp = Path(
        str(path)
        +
        ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            payload,
            f,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def read_json(path):

    with Path(path).open(
        "r",
        encoding="utf-8",
    ) as f:

        return json.load(
            f
        )


def git_blob_bytes(
    ref,
    rel_path,
):

    p = subprocess.run(
        [
            "git",
            "show",
            f"{ref}:{rel_path}",
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )

    if p.returncode != 0:

        raise RuntimeError(
            f"Could not read {rel_path} from {ref}:\n"
            +
            p.stderr.decode(
                "utf-8",
                errors="replace",
            )
        )

    return p.stdout


