# =============================================================================
# 1. HELPERS
# =============================================================================

def banner(text):
    print("\n" + "=" * 118)
    print(text)
    print("=" * 118)


def run(cmd, check=True):
    p = subprocess.run(
        cmd,
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            f"Command failed ({p.returncode}): {' '.join(cmd)}\n"
            f"{p.stdout}"
        )

    return p.stdout.strip()


def git(*args):
    return run(["git", *args])


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        while True:
            block = f.read(8 * 1024 * 1024)

            if not block:
                break

            h.update(block)

    return h.hexdigest()


def read_csv(path):
    with Path(path).open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:
        return list(csv.DictReader(f))


def index_unique(rows, key, label):
    out = {}

    for row in rows:
        value = row[key]

        if value in out:
            raise RuntimeError(
                f"Duplicate {label} key: {value}"
            )

        out[value] = row

    return out


