def banner(s):
    print("\n" + "=" * 124)
    print(s)
    print("=" * 124)

def run(cmd, *, env=None, check=True):
    p = subprocess.run(
        cmd,
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        env=env,
        check=False,
    )
    if check and p.returncode:
        raise RuntimeError(
            f"Command failed ({p.returncode}): {' '.join(cmd)}\n{p.stdout}"
        )
    return p.stdout.strip()

def git(*args, env=None):
    return run(["git", *args], env=env)

def sha(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for block in iter(lambda: f.read(8 * 1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()

def jread(path):
    with Path(path).open("r", encoding="utf-8") as f:
        return json.load(f)

def cread(path):
    with Path(path).open("r", encoding="utf-8", newline="") as f:
        r = csv.DictReader(f)
        return r.fieldnames, list(r)

def blank(v):
    return str(v).strip() == ""

def iv(v, label):
    try:
        return int(str(v).strip())
    except Exception as e:
        raise RuntimeError(f"Invalid int {label}: {v!r}") from e

def fv(v, label):
    try:
        return float(str(v).strip())
    except Exception as e:
        raise RuntimeError(f"Invalid float {label}: {v!r}") from e

def atomic_json(path, obj):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = Path(str(path) + ".tmp")
    with tmp.open("w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2, sort_keys=True, allow_nan=False)
        f.write("\n")
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)

def blob(ref, rel):
    p = subprocess.run(
        ["git", "show", f"{ref}:{rel}"],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if p.returncode:
        raise RuntimeError(
            p.stderr.decode("utf-8", errors="replace")
        )
    return p.stdout

def check_manifest(m, label):
    out = []
    seen = set()

    for x in m["files"]:
        rel = x["path"]

        if rel in seen:
            raise RuntimeError(
                f"Duplicate {label} manifest path: {rel}"
            )

        seen.add(rel)
        p = REPO / rel

        if not p.is_file():
            raise FileNotFoundError(p)

        a = sha(p)
        z = p.stat().st_size

        if a != x["sha256"] or z != int(x["size_bytes"]):
            raise RuntimeError(
                f"{label} manifest mismatch: {rel}"
            )

        out.append(rel)

    return out


