mset = {
    "median_baseline_rss_mib",
    "median_loaded_rss_mib",
    "median_peak_rss_mib",
    "median_delta_model_rss_mib",
    "median_delta_peak_rss_mib",
}

if {
    x["memory_metric_name"]
    for x in mem
} != mset:
    raise RuntimeError(
        "Memory metric set changed."
    )

cond = defaultdict(set)
pkg = defaultdict(set)
mkeys = set()

for x in mem:
    b = iv(
        x["batch_size"],
        "memory batch",
    )

    k = (
        x["target_id"],
        x["cpu_mode"],
        b,
        x["memory_metric_name"],
    )

    if k in mkeys:
        raise RuntimeError(
            f"Duplicate memory key {k}"
        )

    mkeys.add(k)

    c = k[:3]

    cond[c].add(
        k[3]
    )

    pkg[
        x["target_id"]
    ].add(
        x["deployment_package_size_mib"]
    )

    p = iv(
        x["planned_repetitions"],
        f"{c} planned",
    )

    q = iv(
        x["pass_repetitions"],
        f"{c} pass",
    )

    o = iv(
        x["resource_limit_oom_repetitions"],
        f"{c} oom",
    )

    to = iv(
        x["timeout_resource_limit_repetitions"],
        f"{c} timeout",
    )

    if (
        p != 5
        or
        q + o + to != p
    ):
        raise RuntimeError(
            f"Memory repetition accounting failed {c}"
        )

    if q > 0:
        fv(
            x["memory_value_mib"],
            f"{k} value",
        )
    elif not blank(
        x["memory_value_mib"]
    ):
        raise RuntimeError(
            f"Memory value imputed {k}"
        )

