def is_ci_column(name: str) -> bool:
    n = name.lower()

    patterns = (
        "_ci_",
        "_ci95_",
        "_ci90_",
        "_ci99_",
        "ci_low",
        "ci_high",
        "ci95_low",
        "ci95_high",
        "confidence_interval",
        "confidence_low",
        "confidence_high",
    )

    if n == "ci":
        return True

    if n.startswith(
        "ci_"
    ):
        return True

    if n.endswith(
        "_ci"
    ):
        return True

    return any(
        p in n
        for p in patterns
    )


