def run(cmd, *, env=None, check=True):

    p = subprocess.run(
        cmd,
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        env=env,
        check=False,
    )

    if check and p.returncode:
        raise RuntimeError(
            f"Command failed ({p.returncode}): "
            f"{' '.join(cmd)}\n{p.stdout}"
        )

    return p.stdout.strip()


def git(*args, env=None):

    return run(
        [
            "git",
            *args,
        ],
        env=env,
    )


def sha(path):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        for block in iter(
            lambda: f.read(
                8 * 1024 * 1024
            ),
            b"",
        ):
            h.update(
                block
            )

    return h.hexdigest()


def jread(path):

    with Path(path).open(
        "r",
        encoding="utf-8",
    ) as f:

        return json.load(
            f
        )


def cread(path):

    with Path(path).open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:

        reader = csv.DictReader(
            f
        )

        return (
            reader.fieldnames,
            list(
                reader
            ),
        )


def blank(value):

    return (
        str(
            value
        ).strip()
        ==
        ""
    )


def iv(value, label):

    try:
        return int(
            str(
                value
            ).strip()
        )

    except Exception as exc:
        raise RuntimeError(
            f"Invalid int {label}: {value!r}"
        ) from exc


def fv(value, label):

    try:
        return float(
            str(
                value
            ).strip()
        )

    except Exception as exc:
        raise RuntimeError(
            f"Invalid float {label}: {value!r}"
        ) from exc


def atomic_json(
    path,
    obj,
):

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    tmp = Path(
        str(
            path
        )
        +
        ".tmp"
    )

    with tmp.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            obj,
            f,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )

        f.write(
            "\n"
        )

        f.flush()

        os.fsync(
            f.fileno()
        )

    os.replace(
        tmp,
        path,
    )


def blob(
    ref,
    rel,
):

    p = subprocess.run(
        [
            "git",
            "show",
            f"{ref}:{rel}",
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )

    if p.returncode:

        raise RuntimeError(
            p.stderr.decode(
                "utf-8",
                errors="replace",
            )
        )

    return p.stdout


def check_manifest(
    manifest,
    label,
):

    output = []
    seen = set()

    for item in manifest[
        "files"
    ]:

        rel = item[
            "path"
        ]

        if rel in seen:
            raise RuntimeError(
                f"Duplicate {label} manifest path: {rel}"
            )

        seen.add(
            rel
        )

        path = (
            REPO
            / rel
        )

        if not path.is_file():
            raise FileNotFoundError(
                path
            )

        actual_sha = sha(
            path
        )

        actual_size = (
            path
            .stat()
            .st_size
        )

        if (
            actual_sha
            !=
            item[
                "sha256"
            ]
            or
            actual_size
            !=
            int(
                item[
                    "size_bytes"
                ]
            )
        ):

            raise RuntimeError(
                f"{label} manifest mismatch: {rel}"
            )

        output.append(
            rel
        )

    return output


# =============================================================================
# CORRECTED TOKEN-AWARE CI DETECTOR
# =============================================================================

def is_ci_column(
    name: str,
) -> bool:

    n = (
        name
        .strip()
        .lower()
    )

    patterns = (
        "_ci_",
        "_ci95_",
        "_ci90_",
        "_ci99_",
        "ci_low",
        "ci_high",
        "ci95_low",
        "ci95_high",
        "ci90_low",
        "ci90_high",
        "ci99_low",
        "ci99_high",
        "confidence_interval",
        "confidence_low",
        "confidence_high",
    )

    if n == "ci":
        return True

    if n.startswith(
        "ci_"
    ):
        return True

    if n.endswith(
        "_ci"
    ):
        return True

    return any(
        pattern in n
        for pattern in patterns
    )


