def banner(text):
    print("\n" + "=" * 122)
    print(text)
    print("=" * 122)


def run(cmd, *, env=None, check=True):
    p = subprocess.run(
        cmd,
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        env=env,
        check=False,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            f"Command failed ({p.returncode}): "
            f"{' '.join(map(str, cmd))}\n{p.stdout}"
        )

    return p.stdout.strip()


def git(*args, env=None, check=True):
    return run(
        ["git", *args],
        env=env,
        check=check,
    )


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        for block in iter(
            lambda: f.read(16 * 1024 * 1024),
            b"",
        ):
            h.update(block)

    return h.hexdigest()


def remote_blob(ref, rel):
    p = subprocess.run(
        [
            "git",
            "show",
            f"{ref}:{rel}",
        ],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stderr.decode(
                "utf-8",
                errors="replace",
            )
        )

    return p.stdout


