def banner(text):
    print('\n' + '=' * 124)
    print(text)
    print('=' * 124)


def run(cmd, *, cwd=REPO, env=None, check=True):
    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        env=env,
        check=False,
    )
    if check and p.returncode != 0:
        raise RuntimeError(f"Command failed ({p.returncode}): {' '.join(map(str, cmd))}\n{p.stdout}")
    return p.stdout.strip()


def git(*args, env=None, check=True):
    return run(['git', *args], env=env, check=check)


def sha256_file(path, chunk=16 * 1024 * 1024):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda: f.read(chunk), b''):
            h.update(block)
    return h.hexdigest()


def atomic_json(path, obj):
    tmp = Path(str(path) + '.tmp')
    with tmp.open('w', encoding='utf-8') as f:
        json.dump(obj, f, indent=2, sort_keys=True, allow_nan=False)
        f.write('\n')
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def remote_blob(ref, rel):
    p = subprocess.run(
        ['git', 'show', f'{ref}:{rel}'],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if p.returncode != 0:
        raise RuntimeError(p.stderr.decode('utf-8', errors='replace'))
    return p.stdout


def is_blank(v):
    return pd.isna(v) or str(v).strip() == ''


