def banner(text):
    print()
    print("=" * 122)
    print(text)
    print("=" * 122)


def git(*args):
    p = subprocess.run(
        ["git", *args],
        cwd=REPO,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if p.returncode != 0:
        raise RuntimeError(p.stdout)

    return p.stdout.strip()


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        for block in iter(
            lambda: f.read(16 * 1024 * 1024),
            b"",
        ):
            h.update(block)

    return h.hexdigest()


def f3(x):
    return f"{float(x):.3f}"


def f2(x):
    return f"{float(x):.2f}"


def f6(x):
    return f"{float(x):.6f}"


def inv_ratio(x):
    x = float(x)

    if x <= 0:
        return np.nan

    return 1.0 / x


