def row_for(target, batch):
    z = matched[
        (matched["target_id"] == target)
        &
        (matched["batch_size"] == batch)
    ]

    if len(z) != 1:
        raise RuntimeError(
            f"Expected one row for {target} B{batch}, got {len(z)}"
        )

    return z.iloc[0]


