def max_gpu_peak(target):
    z = gpu_pass[
        gpu_pass["target_id"] == target
    ].copy()

    z = z.dropna(
        subset=[
            "delta_peak_gpu_memory_mib"
        ]
    )

    if z.empty:
        raise RuntimeError(
            f"No GPU memory data for {target}"
        )

    idx = z[
        "delta_peak_gpu_memory_mib"
    ].idxmax()

    return z.loc[idx]


