def banner(text):
    print()
    print("=" * 122)
    print(text)
    print("=" * 122)


def run(cmd, *, cwd=None, env=None, check=True):
    p = subprocess.run(
        cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            f"Command failed ({p.returncode}): "
            f"{' '.join(map(str, cmd))}\n\n"
            f"{p.stdout}"
        )

    return p.stdout.strip()


def git(*args, env=None, check=True):
    return run(
        ["git", *args],
        cwd=REPO,
        env=env,
        check=check,
    )


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        for block in iter(
            lambda: f.read(16 * 1024 * 1024),
            b"",
        ):
            h.update(block)

    return h.hexdigest()


def f2(x):
    return f"{float(x):.2f}"


def f3(x):
    return f"{float(x):.3f}"


def f6(x):
    return f"{float(x):.6f}"


def reciprocal(x):
    x = float(x)

    if x <= 0:
        raise ValueError(
            "Cannot take reciprocal of non-positive ratio."
        )

    return 1.0 / x


def one_row(df, target, batch=None):
    z = df[
        df["target_id"] == target
    ]

    if batch is not None:
        z = z[
            z["batch_size"] == batch
        ]

    if len(z) != 1:
        raise RuntimeError(
            f"Expected exactly one row for {target}, "
            f"batch={batch}; got {len(z)}"
        )

    return z.iloc[0]


