def max_memory_row(target):
    z = gpu[
        (gpu["target_id"] == target)
        &
        (gpu["status"] == "PASS")
    ].copy()

    z = z.dropna(
        subset=[
            "delta_peak_gpu_memory_mib"
        ]
    )

    if z.empty:
        raise RuntimeError(
            f"No PASS GPU memory rows for {target}"
        )

    i = z[
        "delta_peak_gpu_memory_mib"
    ].idxmax()

    return z.loc[i]


