def banner(text):
    print()
    print("=" * 124)
    print(text)
    print("=" * 124)


def run(cmd, *, cwd=REPO, check=True):
    p = subprocess.run(
        cmd,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        text=True,
        check=False,
    )

    if check and p.returncode != 0:
        raise RuntimeError(
            f"Command failed ({p.returncode}): "
            f"{' '.join(map(str, cmd))}\n\n"
            f"{p.stdout}"
        )

    return p.stdout.strip()


def git(*args, check=True):
    return run(
        ["git", *args],
        check=check,
    )


def sha256_file(path):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        for block in iter(
            lambda: f.read(16 * 1024 * 1024),
            b"",
        ):
            h.update(block)

    return h.hexdigest()


def human_bytes(n):
    n = int(n)

    if n >= 1024**3:
        return f"{n / 1024**3:.3f} GiB"

    if n >= 1024**2:
        return f"{n / 1024**2:.3f} MiB"

    if n >= 1024:
        return f"{n / 1024:.3f} KiB"

    return f"{n} B"


def ensure_file(path):
    path = Path(path)

    if not path.is_file():
        raise FileNotFoundError(path)

    return path


def ensure_dir(path):
    path = Path(path)

    if not path.is_dir():
        raise FileNotFoundError(path)

    return path


def relative_repo(path):
    return str(
        Path(path).relative_to(REPO)
    )


def copy_verified(src, dst, role, provenance):
    src = ensure_file(src)
    dst = Path(dst)

    dst.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    src_sha = sha256_file(src)

    shutil.copyfile(
        src,
        dst,
    )

    dst_sha = sha256_file(dst)

    if src_sha != dst_sha:
        raise RuntimeError(
            f"Byte-copy mismatch:\n"
            f"source={src}\n"
            f"dest={dst}"
        )

    provenance.append(
        {
            "role": role,
            "source_repository_path":
                relative_repo(src),

            "destination_repository_path":
                str(
                    dst.relative_to(
                        BUILD
                    )
                ),

            "bytes":
                int(
                    dst.stat().st_size
                ),

            "sha256":
                dst_sha,

            "copy_mode":
                "BYTE_FOR_BYTE",
        }
    )


def write_text_file(path, text):
    path = Path(path)

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    path.write_text(
        text.rstrip() + "\n",
        encoding="utf-8",
    )


